var NLP_MODS={"m0": {"slug": "00-tien-quyet", "num": 0, "label": "Module 0", "title": "Kiến thức tiên quyết"}, "m1": {"slug": "01-tap-loi-ham-loi", "num": 1, "label": "Module 1", "title": "Tập lồi và hàm lồi"}, "m2": {"slug": "02-rang-buoc-kkt", "num": 2, "label": "Module 2", "title": "Tối ưu có ràng buộc và điều kiện KKT"}, "m3": {"slug": "03-quy-hoach-toan-phuong", "num": 3, "label": "Module 3", "title": "Quy hoạch toàn phương"}, "m4": {"slug": "04-chuan-bi", "num": 4, "label": "Module chuẩn bị", "title": "Giải bài KKT từng bước"}, "d4": {"slug": "05-doi-ngau-toi-uu-hoa", "num": 5, "label": "Module 4", "title": "Đối ngẫu trong tối ưu hóa"}, "d5": {"slug": "06-doi-ngau-lp-nlp", "num": 6, "label": "Module 5", "title": "Đối ngẫu LP, Lagrange, yên ngựa và KKT"}, "d6": {"slug": "07-rang-buoc-kkt-cap-nhat", "num": 7, "label": "Module 6", "title": "Tối ưu có ràng buộc: điều kiện cực trị (bản cập nhật)"}, "d7": {"slug": "08-toi-uu-khong-rang-buoc", "num": 8, "label": "Module 7", "title": "Tối ưu không ràng buộc: điều kiện cực trị và phương pháp số"}};
var NLP_G=[{"id": "bai-toan-toi-uu", "mod": "m0", "term": "Bài toán tối ưu, infimum và nghiệm", "en": "optimization problem, objective function, feasible set, infimum, minimizer, global minimum", "kind": "Khái niệm", "nomna": "Tìm giá trị nhỏ nhất (hoặc lớn nhất) của một đại lượng khi bạn được chọn trong một tập lựa chọn hợp lệ. Có khi “nhỏ nhất” chỉ tiến sát chứ không bao giờ chạm tới — khi đó ta nói về infimum.", "short": "\\(\\min f(x)\\) s.t. \\(x\\in\\Omega\\): \\(\\Omega\\) là tập khả thi , \\(f\\) là hàm mục tiêu. \\(x^*\\) là nghiệm tối ưu (toàn cục) nếu \\(x^*\\in\\Omega\\) và \\(f(x^*)\\le f(x)\\ \\forall x\\in\\Omega\\). Infimum \\(\\inf f\\) là cận dưới lớn nhất — có thể không đạt. \\(\\max f=-\\min", "dn": ["Chọn quán cơm rẻ nhất trong bán kính 1 km quanh nhà: “rẻ nhất” là hàm mục tiêu, “1 km” là tập khả thi.", "Giá điện thoại cứ giảm sát 0 đồng trong đợt sale nhưng không bao giờ đúng 0: “giá thấp nhất” có thể chỉ là infimum, không ai mua được đúng mức đó."], "hay": "Bài inf Có nghiệm? \\(\\min e^x\\) trên \\(\\mathbb R\\) 0 không (không đạt) \\(\\min1/x\\) trên \\((0,\\infty)\\) 0 không \\(\\min x^2\\) trên \\(\\mathbb R\\) 0 có, \\(x^*=0\\) \\(\\min x\\) trên \\(\\mathbb R\\) \\(-\\infty\\) không (không bị chặn) \\(\\min e^x\\): \\(e^x>0\\) với mọi x nên 0 là cận dưới; với mọi \\(\\varepsilon>0\\) chọn \\(x=\\ln\\varepsilon\\) cho \\(e^x=\\varepsilon\\) ⇒ cận dưới lớn nhất là 0, nhưng không x nào cho \\(e^x=0\\) ⇒ infimum 0 không đạt."}, {"id": "gradient", "mod": "m0", "term": "Gradient", "en": "gradient, partial derivatives, steepest ascent, directional derivative, level curve", "kind": "Khái niệm", "nomna": "Gradient là mũi tên chỉ hướng dốc nhất lên núi tại điểm bạn đứng; độ dài mũi tên là độ dốc. Đi ngược mũi tên là xuống dốc nhanh nhất.", "short": "\\(\\nabla f(x)=\\big(\\partial f/\\partial x_1,\\dots,\\partial f/\\partial x_n\\big)^\\top\\). Đạo hàm theo hướng \\(d\\): \\(f^\\prime(x;d)=\\nabla f(x)^\\top d\\). Hướng giảm nhanh nhất là \\(-\\nabla f\\); \\(\\nabla f\\) vuông góc với đường mức.", "dn": ["Đứng giữa sườn đồi, hướng mũi giày chỉ dốc lên nhất chính là hướng gradient; quay lưng lại là hướng xuống nhanh nhất.", "Phòng có bếp: nhiệt độ tăng nhanh nhất theo hướng về phía bếp — đó là gradient của nhiệt độ."], "hay": "\\(f=x^2y+y^3\\) tại \\((1,2)\\). ① \\(f_x=2xy=4\\). ② \\(f_y=x^2+3y^2=1+12=13\\). ③ \\(\\nabla f(1,2)=(4,13)\\); hướng giảm nhanh nhất \\(-(4,13)\\)."}, {"id": "hessian", "mod": "m0", "term": "Hessian", "en": "Hessian matrix, second derivative, curvature, second-order partial derivatives", "kind": "Khái niệm", "nomna": "Gradient nói bạn đang dốc bao nhiêu; Hessian nói “độ dốc ấy đang thay đổi thế nào” — mặt đất cong lên như bát, cong xuống như mái vòm, hay yên ngựa.", "short": "\\(\\nabla^2f(x)=\\big[\\partial^2f/\\partial x_i\\partial x_j\\big]\\), đối xứng khi \\(f\\in C^2\\). Độ cong theo hướng \\(d\\): \\(d^\\top\\nabla^2f\\,d\\). Giá trị riêng của H là độ cong theo các trục chính.", "dn": ["Đáy chảo: đi hướng nào cũng lên (Hessian xác định dương). Yên ngựa: lên theo trục này, xuống theo trục kia (không xác định).", "Khúc cua: gradient là độ nghiêng của đường, Hessian là độ “gắt” của khúc cua theo từng hướng."], "hay": "\\(f=x^2y+y^3\\) tại \\((1,2)\\): \\(f_{xx}=2y=4\\), \\(f_{xy}=2x=2\\), \\(f_{yy}=6y=12\\) ⇒ \\(H=\\begin{pmatrix}4&2\\\\2&12\\end{pmatrix}\\). \\(D_1=4>0\\), \\(\\det=48-4=44>0\\) ⇒ PD: cong lên mọi hướng quanh \\((1,2)\\)."}, {"id": "diem-dung", "mod": "m0", "term": "Điểm dừng và điều kiện cấp 1, cấp 2", "en": "stationary point, critical point, first-order necessary condition, second-order sufficient condition, saddle point", "kind": "Mệnh đề", "nomna": "Điểm dừng là chỗ mặt đất bằng phẳng (không dốc theo hướng nào). Bằng phẳng có thể là đáy bát, đỉnh đồi, hay yên ngựa; xét độ cong (Hessian) để biết là loại nào.", "short": "Cấp 1 (cần): cực tiểu địa phương không ràng buộc ⇒ \\(\\nabla f(x^*)=0\\). Cấp 2 (cần): \\(\\nabla^2f(x^*)\\succeq0\\). Cấp 2 (đủ): \\(\\nabla f=0\\) và \\(\\nabla^2f\\succ0\\) ⇒ cực tiểu địa phương chặt.", "dn": ["Đỉnh đồi, đáy thung lũng và khe đèo đều có chỗ đứng “bằng phẳng”, nhưng chỉ đáy thung lũng là cực tiểu.", "Viên bi đặt ngay đáy chảo thì đứng yên bền; đặt ngay đỉnh mái vòm cũng đứng yên về lý thuyết nhưng chạm nhẹ là lăn đi."], "hay": "Hessian tại điểm dừng Loại \\(\\succ0\\) cực tiểu địa phương \\(\\prec0\\) cực đại địa phương không xác định yên ngựa \\(\\succeq0\\) có giá trị riêng 0 chưa kết luận (ví dụ \\(x^4\\)) \\(f=x^3-3x+y^2\\). ① \\(\\nabla f=(3x^2-3,\\ 2y)=0\\Rightarrow x=\\pm1,\\ y=0\\). ② \\(H=\\mathrm{diag}(6x,\\ 2)\\). ③ \\((1,0)\\): \\(H=\\mathrm{diag}(6,2)\\succ0\\) ⇒ cực tiểu địa phương, \\(f=-2\\). ④ \\((-1,0)\\): \\(H=\\mathrm{diag}(-6,2)\\) không xác định ⇒ yên ngựa, \\(f=2\\). ⑤ Không có cực tiểu toàn cục vì \\(f(x,0)\\to-\\infty\\) khi \\(x\\to-\\infty\\)."}, {"id": "taylor", "mod": "m0", "term": "Khai triển Taylor bậc hai", "en": "Taylor expansion, second-order approximation, quadratic model, Newton method", "kind": "Khái niệm", "nomna": "Ở rất gần một điểm, mọi hàm trơn trông như một cái bát (hoặc mái) bậc hai: gần đúng bằng mặt phẳng tiếp xúc cộng thêm phần cong.", "short": "\\(f(p+d)\\approx f(p)+\\nabla f(p)^\\top d+\\tfrac12d^\\top\\nabla^2f(p)\\,d\\); sai số \\(O(\\lVert d\\rVert^3)\\).", "dn": ["Phóng to bản đồ: ở thật gần, đường cong trông như đường thẳng; phóng to hơn nữa mới thấy nó hơi cong.", "Ước phanh xe: quãng đường ≈ vận tốc × thời gian (bậc 1) cộng một phần nửa gia tốc × thời gian bình phương (bậc 2)."], "hay": "\\(f=e^x+xy\\), \\(p=(0,0)\\), \\(d=(0.1,0.2)\\). ① \\(f(p)=1\\). ② \\(\\nabla f=(e^x+y,\\ x)=(1,0)\\) ⇒ \\(\\nabla f^\\top d=0.1\\). ③ \\(H=\\begin{pmatrix}1&1\\\\1&0\\end{pmatrix}\\): \\(d^\\top Hd=0.01+2\\cdot0.1\\cdot0.2=0.05\\) ⇒ nửa là 0.025. ④ Xấp xỉ \\(=1+0.1+0.025=1.125\\); thật \\(e^{0.1}+0.02=1.12517\\)."}, {"id": "tri-rieng", "mod": "m0", "term": "Giá trị riêng, định thức, vết", "en": "eigenvalue, eigenvector, determinant, trace, characteristic polynomial, spectral theorem", "kind": "Khái niệm", "nomna": "Giá trị riêng là “hệ số co giãn” của ma trận theo các hướng đặc biệt; định thức là hệ số co giãn thể tích (tích các giá trị riêng); vết là tổng.", "short": "\\(Av=\\lambda v\\), \\(v\\ne0\\). Đa thức đặc trưng \\(\\det(A-\\lambda I)=0\\). Với 2×2: \\(\\lambda^2-\\operatorname{tr}(A)\\lambda+\\det A=0\\); \\(\\sum\\lambda_i=\\operatorname{tr}A\\), \\(\\prod\\lambda_i=\\det A\\). Ma trận đối xứng thực có giá trị riêng thực.", "dn": ["Kéo giãn tấm cao su: có những hướng đặc biệt mà tấm cao su chỉ co giãn chứ không xoay — hệ số giãn đó là giá trị riêng.", "Dây đàn: mỗi tần số rung riêng là một giá trị riêng của hệ."], "hay": "\\(A=\\begin{pmatrix}2&1\\\\1&3\\end{pmatrix}\\). ① \\(\\operatorname{tr}=5\\), \\(\\det=6-1=5\\). ② \\(\\lambda^2-5\\lambda+5=0\\Rightarrow\\lambda=\\dfrac{5\\pm\\sqrt5}{2}\\approx3.618,\\ 1.382\\). ③ Kiểm: tổng \\(=5\\), tích \\(=(25-5)/4=5\\) ✔; cả hai dương ⇒ A xác định dương. Nghịch đảo: \\(A^{-1}=\\tfrac15\\begin{pmatrix}3&-1\\\\-1&2\\end{pmatrix}\\)."}, {"id": "weierstrass", "mod": "m0", "term": "Tồn tại cực tiểu: compact và coercive", "en": "Weierstrass extreme value theorem, compact set, coercive function, existence of minimum", "kind": "Mệnh đề", "nomna": "Muốn chắc có đáy thật thì sân chơi phải “gọn và đóng kín” (compact), hoặc sàn phải dốc lên vô tận ở xa (coercive) để đáy không trốn ra vô cùng.", "short": "Weierstrass: \\(f\\) liên tục trên tập compact (đóng, bị chặn) ⇒ đạt min và max. Coercive: \\(f(x)\\to\\infty\\) khi \\(\\lVert x\\rVert\\to\\infty\\); liên tục + coercive trên tập đóng ⇒ có cực tiểu toàn cục.", "dn": ["Tìm chỗ thấp nhất trong một mảnh vườn có hàng rào kín: chắc chắn có.", "Tìm chỗ thấp nhất trên bãi không rào mà càng đi xa đất càng dốc lên (coercive): vẫn có đáy; nếu càng xa đất càng dốc xuống thì không có đáy."], "hay": "\\(f=x^2+y^2\\): với \\(\\lVert(x,y)\\rVert\\ge R\\) thì \\(f\\ge R^2\\) ⇒ coercive ⇒ có cực tiểu (gốc, \\(f=0\\)). \\(f=e^x\\) không coercive (\\(\\to0\\) khi \\(x\\to-\\infty\\)) ⇒ không đạt cực tiểu. \\(f=x^3\\) không bị chặn dưới."}, {"id": "doi-ngau-lp", "mod": "m0", "term": "Đối ngẫu LP và độ lệch bù", "en": "LP duality, dual problem, strong duality, weak duality, complementary slackness, shadow price", "kind": "Mệnh đề", "nomna": "Mỗi bài “người sản xuất tối đa lợi nhuận” có một bài song sinh “người định giá nguồn lực tối thiểu tổng giá trị”. Hai bài luôn cho cùng một con số khi đều có nghiệm.", "short": "Gốc: \\(\\max c^\\top x\\) s.t. \\(Ax\\le b\\), \\(x\\ge0\\). Đối ngẫu: \\(\\min b^\\top y\\) s.t. \\(A^\\top y\\ge c\\), \\(y\\ge0\\). Đối ngẫu mạnh : cùng tối ưu thì \\(c^\\top x^*=b^\\top y^*\\). Độ lệch bù : \\(y_i(b_i-a_i^\\top x)=0\\), \\(x_j(a_j^\\top y-c_j)=0\\).", "dn": ["Chủ xưởng muốn tối đa lãi, người định giá nguyên liệu muốn tổng giá trị mua ít nhất; khi mặc cả xong, giá nguyên liệu khớp với lãi: hai bài cho cùng một số.", "Hãng xe và khách thuê: khách giảm chi phí, hãng tăng doanh thu; giá cân bằng chính là nghiệm đối ngẫu."], "hay": "Bài gốc (max) Bài đối ngẫu (min) ràng buộc \\(\\le\\) biến \\(y\\ge0\\) ràng buộc \\(=\\) biến \\(y\\) tự do biến \\(x\\ge0\\) ràng buộc \\(\\ge\\) \\(\\max3x_1+2x_2\\) s.t. \\(x_1+x_2\\le4,\\ x_1+3x_2\\le6,\\ x\\ge0\\). ① Đỉnh: \\((0,0)\\to0\\); \\((4,0)\\to12\\); \\((3,1)\\to11\\); \\((0,2)\\to4\\) ⇒ max 12 tại \\((4,0)\\). ② Đối ngẫu: \\(\\min4y_1+6y_2\\) s.t. \\(y_1+y_2\\ge3\\), \\(y_1+3y_2\\ge2\\), \\(y\\ge0\\). ③ Thử \\(y=(3,0)\\): \\(3\\ge3\\) ✔, \\(3\\ge2\\) ✔, giá trị 12 = gốc. ④ Độ lệch bù: ràng buộc 2 gốc không chặt (\\(4+0=4"}, {"id": "cuc-tieu-dp", "mod": "m0", "term": "Cực tiểu địa phương và toàn cục", "en": "local minimum, global minimum, strict local minimizer", "kind": "Khái niệm", "nomna": "Địa phương: đáy của một cái hố trong vùng bạn nhìn thấy. Toàn cục: đáy thấp nhất của cả vùng. Trên đồi núi có nhiều hố; trong cái bát chỉ có một.", "short": "\\(x^*\\) là cực tiểu địa phương nếu tồn tại \\(\\delta>0\\) sao cho \\(f(x^*)\\le f(x)\\) với mọi khả thi \\(x\\) trong \\(\\lVert x-x^*\\rVert", "dn": ["Một hố trên đường: nằm đáy hố bạn thấy “thấp nhất quanh đây” nhưng cả thành phố còn hồ sâu hơn.", "Quán phở ngon nhất phố nhà bạn (địa phương) khác quán ngon nhất cả nước (toàn cục)."], "hay": "\\(f=x^4-2x^2\\): \\(f^\\prime=4x^3-4x=0\\Rightarrow x\\in\\{0,\\pm1\\}\\); \\(f^{\\prime\\prime}=12x^2-4\\): tại \\(\\pm1\\): \\(8>0\\) (cực tiểu, \\(f=-1\\)); tại 0: \\(-4"}, {"id": "dinh-thuc", "mod": "m0", "term": "Định thức và ma trận nghịch đảo", "en": "determinant, matrix inverse, singular matrix, adjugate, Cramer rule, area scaling", "kind": "Phép toán", "nomna": "Định thức cho biết ma trận “phóng to hay thu nhỏ diện tích (thể tích)” bao nhiêu lần; bằng 0 nghĩa là ma trận ép mọi thứ xẹp thành một đường — không thể quay ngược lại (không khả nghịch).", "short": "2×2: \\(\\det\\begin{pmatrix}a&b\\\\c&d\\end{pmatrix}=ad-bc\\); \\(A^{-1}=\\tfrac1{\\det A}\\begin{pmatrix}d&-b\\\\-c&a\\end{pmatrix}\\). 3×3: khai triển theo hàng/cột. Tính chất: \\(\\det(AB)=\\det A\\det B\\), \\(\\det A^\\top=\\det A\\), \\(\\det A=\\prod\\lambda_i\\), \\(A\\) khả nghịch ", "dn": ["Kéo giãn một tờ giấy: định thức là hệ số thay đổi diện tích ; nếu bằng 0 thì tờ giấy bị ép phẳng thành một đoạn (mất thông tin, không khôi phục được).", "Công thức nghịch đảo giống “tua ngược băng”: chỉ tua được khi băng chưa bị ép phẳng (định thức khác 0)."], "hay": "Phép Công thức 2×2 \\(ad-bc\\) 3×3 (hàng 1) \\(a_{11}M_{11}-a_{12}M_{12}+a_{13}M_{13}\\) nghịch đảo \\(A^{-1}=\\operatorname{adj}A/\\det A\\) hệ \\(Ax=b\\) Cramer: \\(x_i=\\det A_i/\\det A\\) \\(B=\\begin{pmatrix}1&2&0\\\\0&1&3\\\\2&0&1\\end{pmatrix}\\), khai triển theo hàng 1: ① \\(M_{11}=\\det\\begin{pmatrix}1&3\\\\0&1\\end{pmatrix}=1\\). ② \\(M_{12}=\\det\\begin{pmatrix}0&3\\\\2&1\\end{pmatrix}=0-6=-6\\). ③ \\(M_{13}\\) nhân với \\(a_{13}=0\\) nên bỏ. ④ \\(\\det B=1\\cdot1-2\\cdot(-6)+0=13\\). Kiểm: \\(\\det\\begin{pmatrix}2&1\\\\1&3\\end{pmatrix}=5\\), diện tích hình bình hành căng bởi \\((2,1)\\) và \\((1,3)\\) cũng là 5."}, {"id": "tap-loi", "mod": "m1", "term": "Tập lồi", "en": "convex set, convexity, line segment, convex combination, midpoint", "kind": "Khái niệm", "nomna": "Một vùng mà nếu bạn đứng ở hai điểm bất kỳ trong vùng và căng sợi dây thẳng giữa chúng thì sợi dây không bao giờ chui ra ngoài. Hình tròn, hình vuông, nửa mặt phẳng đều “căng dây được”; hình trăng khuyết hay hình chữ U thì không.", "short": "Tập \\(C\\subseteq\\mathbb R^n\\) là lồi nếu với mọi \\(x,y\\in C\\) và mọi \\(\\theta\\in[0,1]\\) thì \\(\\theta x+(1-\\theta)y\\in C\\). Điểm \\(\\theta x+(1-\\theta)y\\) chạy từ \\(y\\) (\\(\\theta=0\\)) đến \\(x\\) (\\(\\theta=1\\)) trên đoạn \\([x,y]\\). Tập rỗng và tập một điểm cũng lồ", "dn": ["Căn phòng hình chữ nhật: đứng ở hai góc bất kỳ, căng dây giữa hai người thì dây nằm trong phòng. Phòng hình chữ L thì có hai góc mà dây đi xuyên tường.", "Cái bánh pizza tròn lồi; cái bánh quy hình vầng trăng khuyết thì không."], "hay": "Tập Lồi? Lý do ngắn \\(\\{x:\\ \\lVert x\\rVert\\le1\\}\\) (đĩa) có tập mức dưới của hàm lồi \\(\\{x:\\ \\lVert x\\rVert=1\\}\\) (đường tròn) không trung điểm hai điểm đối xứng là gốc, không nằm trên đường tròn \\([0,1]\\cup[2,3]\\) không đoạn nối 1 và 2 đi qua khoảng trống \\(\\{x:\\ a^\\top x\\le b\\}\\) có nửa không gian Kiểm tra bằng định nghĩa. \\(S=\\{x_1x_2\\ge1\\}\\). Chọn \\(x=(1,1)\\), \\(y=(-1,-1)\\) (cả hai thoả \\(x_1x_2=1\\)). Với \\(\\theta=\\tfrac12\\): \\(z=(0,0)\\). Vì \\(0\\cdot0=0 không lồi (một phản ví dụ là đủ)."}, {"id": "to-hop-loi", "mod": "m1", "term": "Tổ hợp lồi và bao lồi", "en": "convex combination, convex hull, conv S, barycentric coordinates, simplex", "kind": "Khái niệm", "nomna": "Tổ hợp lồi là “pha trộn theo tỉ lệ” các điểm: như pha cà phê từ ba loại hạt, tỉ lệ cộng lại đúng 100%. Bao lồi là tất cả các hỗn hợp có thể pha được — hình dạng thu được khi bạn căng một màng chun quanh các điểm.", "short": "Tổ hợp lồi của \\(v_1,\\dots,v_k\\): \\(x=\\sum_i\\lambda_iv_i\\) với \\(\\lambda_i\\ge0\\), \\(\\sum_i\\lambda_i=1\\). Bao lồi \\(\\operatorname{conv}S\\) = tập mọi tổ hợp lồi (hữu hạn) của điểm trong S = tập lồi nhỏ nhất chứa S = giao của mọi tập lồi chứa S.", "dn": ["Pha cà phê từ 3 loại hạt với tỉ lệ cộng lại đúng 100%: mọi vị cà phê pha được nằm “giữa” ba loại hạt gốc.", "Điểm kiểm tra tích luỹ: điểm tổng kết là trung bình có trọng số các điểm thành phần, trọng số cộng bằng 1."], "hay": "Điều kiện cần kiểm Ý nghĩa \\(\\lambda_i\\ge0\\) không “trừ” bớt nguyên liệu \\(\\sum\\lambda_i=1\\) tỉ lệ cộng lại đủ 100% \\(x=\\sum\\lambda_iv_i\\) khớp từng toạ độ \\(x=(1,1)\\) có thuộc \\(\\operatorname{conv}\\{v_1=(0,0),v_2=(3,0),v_3=(0,3)\\}\\) không? ① Toạ độ thứ nhất: \\(3\\lambda_2=1\\Rightarrow\\lambda_2=1/3\\). ② Toạ độ thứ hai: \\(3\\lambda_3=1\\Rightarrow\\lambda_3=1/3\\). ③ \\(\\lambda_1=1-\\lambda_2-\\lambda_3=1/3\\). ④ Cả ba \\(\\ge0\\) và tổng bằng 1 ⇒ có (là trọng tâm tam giác). Với \\(x=(2,2)\\): \\(\\lambda_2=\\lambda_3=2/3\\Rightarrow\\lambda_1=-1/3"}, {"id": "sieu-phang", "mod": "m1", "term": "Siêu phẳng và nửa không gian", "en": "hyperplane, half-space, normal vector, separating hyperplane, distance to hyperplane", "kind": "Khái niệm", "nomna": "Siêu phẳng là “bức tường phẳng” chia không gian làm hai nửa: trong mặt phẳng nó là đường thẳng, trong không gian 3 chiều nó là mặt phẳng. Nửa không gian là một bên của bức tường (kể cả tường).", "short": "Siêu phẳng \\(H=\\{x:\\ a^\\top x=b\\}\\) (\\(a\\ne0\\)); \\(a\\) là vectơ pháp tuyến (vuông góc với mọi hướng nằm trong H). Nửa không gian đóng: \\(\\{a^\\top x\\le b\\}\\) hoặc \\(\\{a^\\top x\\ge b\\}\\) — đều lồi. Khoảng cách từ điểm \\(p\\) đến H là \\(|a^\\top p-b|/\\lVert a\\rVert\\", "dn": ["Bức tường chia căn nhà thành hai phía; vectơ pháp tuyến là mũi tên chỉ thẳng ra khỏi tường, vuông góc với mặt tường.", "Ranh giới ngân sách: bên dưới đường “vừa đủ tiền” là mua được, bên trên thì không."], "hay": "\\(H:\\ 3x_1+4x_2=10\\), điểm \\(p=(1,1)\\). ① \\(a^\\top p=3+4=7\\), \\(b=10\\) ⇒ \\(a^\\top p-b=-3\\). ② \\(\\lVert a\\rVert=\\sqrt{9+16}=5\\). ③ Khoảng cách \\(=3/5=0.6\\). Dấu âm: \\(p\\) nằm ở phía \\(a^\\top x Khoảng cách từ gốc đến H: \\(10/5=2\\)."}, {"id": "cuc-bien", "mod": "m1", "term": "Điểm cực biên", "en": "extreme point, vertex, polyhedron, polytope, basic feasible solution", "kind": "Khái niệm", "nomna": "Đỉnh nhọn của một hình: chỗ mà bạn không thể coi nó là “điểm giữa” của hai điểm khác trong hình. Trung điểm cạnh thì không phải đỉnh (nó nằm giữa hai đỉnh).", "short": "\\(x\\in C\\) là điểm cực biên nếu \\(x=\\lambda x_1+(1-\\lambda)x_2\\) với \\(x_1,x_2\\in C\\), \\(\\lambda\\in(0,1)\\) kéo theo \\(x_1=x_2=x\\). Với đa diện \\(\\{Ax\\le b\\}\\) trong \\(\\mathbb R^n\\): cực biên ⇔ có \\(n\\) ràng buộc độc lập tuyến tính cùng chặt. Đa diện bị chặn = ", "dn": ["Góc nhọn của tờ giấy: không thể nằm “chính giữa” hai điểm khác trên tờ giấy. Trung điểm cạnh thì có.", "Cái bàn hình vuông chỉ có bốn góc là “mép nhọn”; điểm bất kỳ trên cạnh nằm giữa hai góc."], "hay": "Tập Số điểm cực biên hình vuông 4 tam giác 3 đĩa tròn vô hạn (cả đường tròn) nửa mặt phẳng 0 \\(S=\\{x_1\\ge0,\\ x_2\\ge0,\\ x_1+x_2\\le4,\\ x_1\\le3\\}\\). Mỗi đỉnh là giao của 2 ràng buộc chặt: • \\(x_1=0,x_2=0\\Rightarrow(0,0)\\) khả thi ✔ • \\(x_1=0,x_1+x_2=4\\Rightarrow(0,4)\\) ✔ • \\(x_2=0,x_1+x_2=4\\Rightarrow(4,0)\\): vi phạm \\(x_1\\le3\\) ✘ • \\(x_2=0,x_1=3\\Rightarrow(3,0)\\) ✔ • \\(x_1+x_2=4,x_1=3\\Rightarrow(3,1)\\) ✔ Bốn đỉnh: \\((0,0),(0,4),(3,0),(3,1)\\)."}, {"id": "phep-toan-loi", "mod": "m1", "term": "Các phép toán giữ tính lồi (tập)", "en": "operations preserving convexity, intersection, affine image, Minkowski sum, union", "kind": "Khái niệm", "nomna": "Bạn được phép “cắt”, “co giãn”, “dịch” hay “chiếu” một hình lồi mà nó vẫn lồi; nhưng “dán hai hình lại” (hợp) hay “khoét” (phần bù) thì có thể làm mất tính lồi.", "short": "Giao (kể cả vô hạn) các tập lồi là lồi. Ảnh \\(AS+b\\) và tiền ảnh \\(\\{x:Ax+b\\in S\\}\\) của tập lồi qua ánh xạ afin là lồi. Tổng Minkowski \\(S_1+S_2\\) và tích Đề-các \\(S_1\\times S_2\\) lồi. Hợp, phần bù: không bảo đảm.", "dn": ["Cắt bánh pizza bằng nhát dao thẳng (giao với nửa mặt phẳng) thì mảnh còn lại vẫn lồi; dán hai miếng bánh rời nhau thì không.", "Phóng to, thu nhỏ hay dịch tấm ảnh một hình lồi thì hình vẫn lồi; “đục lỗ” ở giữa thì mất lồi."], "hay": "Phép toán Giữ lồi? giao có ảnh/tiền ảnh afin có tổng Minkowski có hợp không phần bù không Chứng minh nhanh “giao giữ lồi”: lấy \\(x,y\\in\\bigcap C_i\\). Với mỗi i, \\(x,y\\in C_i\\) lồi ⇒ \\([x,y]\\subseteq C_i\\). Vậy \\([x,y]\\subseteq\\bigcap C_i\\). Phản ví dụ cho hợp: \\(C_1=[0,1]\\), \\(C_2=[2,3]\\): \\(1,2\\in C_1\\cup C_2\\) nhưng trung điểm \\(1.5\\notin\\)."}, {"id": "ham-loi", "mod": "m1", "term": "Hàm lồi và bất đẳng thức Jensen", "en": "convex function, Jensen inequality, strictly convex, concave function", "kind": "Khái niệm", "nomna": "Hàm lồi có đồ thị hình “cái bát”: nối hai điểm bất kỳ trên đồ thị bằng dây thì dây nằm trên đồ thị. Nghĩa là trung bình của giá trị luôn không nhỏ hơn giá trị của trung bình.", "short": "\\(f:C\\to\\mathbb R\\) (C lồi) là lồi nếu \\(f(\\theta x+(1-\\theta)y)\\le\\theta f(x)+(1-\\theta)f(y)\\) với mọi \\(x,y\\in C\\), \\(\\theta\\in[0,1]\\). Lồi chặt : dấu “ Lõm : \\(-f\\) lồi.", "dn": ["Cái võng căng giữa hai cột: sợi dây võng nằm phía dưới đoạn thẳng nối hai đầu — như đồ thị hàm lồi nằm dưới dây cung.", "Đi 2 chuyến mỗi chuyến chở 50 kg thường tốn ít sức hơn một chuyến 100 kg (sức tăng nhanh dần theo tải): hàm sức tốn lồi."], "hay": "\\(f(x)=x^2\\), \\(x=0\\), \\(y=4\\), \\(\\theta=\\tfrac12\\). ① Vế trái: \\(f(\\tfrac12\\cdot0+\\tfrac12\\cdot4)=f(2)=4\\). ② Vế phải: \\(\\tfrac12f(0)+\\tfrac12f(4)=0+8=8\\). ③ \\(4\\le8\\) ✔ (đúng chiều lồi). Với \\(f(x)=\\ln x\\) (lõm): \\(x=1,y=4\\): \\(f(2.5)=0.916>\\tfrac12(0+1.386)=0.693\\) — chiều ngược lại."}, {"id": "dk-cap1", "mod": "m1", "term": "Điều kiện cấp một: đồ thị nằm trên tiếp tuyến", "en": "first-order condition for convexity, tangent line, supporting hyperplane, gradient inequality", "kind": "Mệnh đề", "nomna": "Với hàm lồi, nếu bạn vẽ tiếp tuyến tại bất kỳ điểm nào thì cả đồ thị đều nằm phía trên tiếp tuyến đó — như cái bát đặt trên tấm ván tiếp xúc ở một điểm.", "short": "Mệnh đề. Với \\(f\\) khả vi trên tập lồi mở, \\(f\\) lồi ⇔ \\(f(y)\\ge f(x)+\\nabla f(x)^\\top(y-x)\\) với mọi \\(x,y\\). Hệ quả: \\(\\nabla f(x^*)=0\\Rightarrow x^*\\) là cực tiểu toàn cục .", "dn": ["Đặt cái bát lên tấm ván phẳng chạm đúng một điểm: cả bát nằm phía trên ván. Tấm ván là tiếp tuyến.", "Ước lượng chi phí bằng cách “nhân đơn giá hiện tại với số lượng thêm”: nếu chi phí tăng nhanh dần thì ước lượng này luôn thấp hơn thật."], "hay": "\\(f=x^2\\), \\(x=1\\), \\(y=3\\): \\(f(1)=1\\), \\(f^\\prime(1)=2\\). Tiếp tuyến tại 1 cho \\(1+2\\cdot(3-1)=5\\); \\(f(3)=9\\ge5\\) ✔. Khoảng cách 4 chính là phần “cong lên” \\((y-x)^2=4\\)."}, {"id": "dk-cap2", "mod": "m1", "term": "Điều kiện cấp hai: Hessian nửa xác định dương", "en": "second-order condition for convexity, Hessian positive semidefinite, convex iff", "kind": "Mệnh đề", "nomna": "Hàm “cong lên” ở mọi hướng. Hessian đo độ cong theo từng hướng; cong lên (hoặc phẳng) ở mọi hướng ⇔ Hessian không có giá trị riêng âm.", "short": "Mệnh đề. \\(f\\) khả vi hai lần trên tập lồi mở: \\(f\\) lồi ⇔ \\(\\nabla^2f(x)\\succeq0\\ \\forall x\\). Nếu \\(\\nabla^2f(x)\\succ0\\ \\forall x\\) thì f lồi chặt (chiều ngược lại không đúng: \\(x^4\\) lồi chặt dù \\(f^{\\prime\\prime}(0)=0\\)).", "dn": ["Mặt bát cong lên mọi hướng: cắt bát theo mặt phẳng nào cũng thấy đường cong lên (độ cong ≥ 0).", "Xe lên dốc: nếu độ dốc tăng dần mọi lúc (không có đoạn dốc dịu lại) thì đường cong “lồi”."], "hay": "Hessian trên toàn miền Kết luận \\(\\succ0\\) lồi chặt \\(\\succeq0\\) lồi \\(\\preceq0\\) lõm dấu đổi theo điểm / giá trị riêng trái dấu không lồi, không lõm \\(f=x_1^2+x_1x_2+x_2^2\\). ① \\(f_{11}=2,\\ f_{22}=2,\\ f_{12}=1\\) ⇒ \\(H=\\begin{pmatrix}2&1\\\\1&2\\end{pmatrix}\\). ② Minor: \\(D_1=2>0\\), \\(D_2=4-1=3>0\\). ③ Giá trị riêng: \\(\\lambda^2-4\\lambda+3=0\\Rightarrow1,3\\) (đều dương). ④ \\(H\\succ0\\) với mọi x ⇒ lồi chặt."}, {"id": "xac-dinh-duong", "mod": "m1", "term": "Ma trận xác định dương và tiêu chuẩn Sylvester", "en": "positive definite matrix, positive semidefinite, Sylvester criterion, leading principal minors, quadratic form", "kind": "Mệnh đề", "nomna": "Ma trận xác định dương là “cái bát tròn trịa”: dù bạn đi hướng nào từ gốc, giá trị \\(x^\\top Ax\\) đều dương. Tiêu chuẩn Sylvester là cách kiểm tra bằng cách tính vài định thức, khỏi phải thử mọi hướng.", "short": "\\(A\\) đối xứng. PD (\\(A\\succ0\\)): \\(x^\\top Ax>0\\ \\forall x\\ne0\\) ⇔ mọi giá trị riêng \\(>0\\) ⇔ mọi minor dẫn đầu \\(D_k>0\\). PSD (\\(A\\succeq0\\)): \\(x^\\top Ax\\ge0\\) ⇔ mọi giá trị riêng \\(\\ge0\\) ⇔ mọi minor chính (không chỉ dẫn đầu) \\(\\ge0\\). ND: \\(D_k\\) đổi dấu x", "dn": ["Đáy chảo tròn: thả viên bi ở hướng nào cũng lăn về tâm — ma trận xác định dương. Máng trượt (rãnh dài) thì dọc rãnh bi không lăn: nửa xác định dương.", "Điều kiện ổn định: một hệ ổn định khi “năng lượng” \\(x^\\top Ax\\) luôn dương với mọi lệch khỏi cân bằng."], "hay": "Ma trận Minor Kết luận \\(\\begin{pmatrix}2&-1&0\\\\-1&2&-1\\\\0&-1&2\\end{pmatrix}\\) \\(D_1,D_2,D_3=2,3,4\\) PD \\(\\begin{pmatrix}1&1\\\\1&1\\end{pmatrix}\\) chính: 1, 1, 0 PSD, không PD \\(\\begin{pmatrix}0&0\\\\0&-1\\end{pmatrix}\\) dẫn đầu 0, 0 nhưng chính \\(a_{22}=-1\\) không PSD \\(\\begin{pmatrix}1&2\\\\2&1\\end{pmatrix}\\) \\(\\det=-3\\) không xác định \\(A=\\begin{pmatrix}2&-1&0\\\\-1&2&-1\\\\0&-1&2\\end{pmatrix}\\). ① \\(D_1=2\\). ② \\(D_2=2\\cdot2-(-1)(-1)=3\\). ③ \\(D_3=2(4-1)-(-1)(-2-0)=6-2=4\\). Cả ba dương ⇒ PD."}, {"id": "epigraph", "mod": "m1", "term": "Epigraph", "en": "epigraph, level set, sublevel set, convex function iff epigraph convex", "kind": "Mệnh đề", "nomna": "Epigraph là phần mặt phẳng nằm “trên mặt đồ thị” — như phần không khí phía trên một cái bát. Hàm lồi khi và chỉ khi cái bát “đặc” đó là tập lồi.", "short": "\\(\\operatorname{epi}f=\\{(x,t):\\ f(x)\\le t\\}\\). Mệnh đề: \\(f\\) lồi ⇔ \\(\\operatorname{epi}f\\) lồi. Tập mức dưới \\(\\{f\\le c\\}\\) của hàm lồi cũng lồi (lát cắt ngang của epigraph).", "dn": ["Phần không khí phía trên mặt nước lòng chảo: tập mọi điểm “trên đáy chảo”. Lòng chảo lồi ⇔ phần không khí lồi.", "Mức giá “trần” cho chi phí: tập mọi cặp (sản lượng, ngân sách đủ chi) là epigraph của hàm chi phí."], "hay": "\\(f=x^2\\): điểm \\((1,2)\\in\\operatorname{epi}f\\) vì \\(2\\ge1\\); \\((1,0.5)\\notin\\) vì \\(0.5"}, {"id": "cuc-tieu-dia-phuong", "mod": "m1", "term": "Cực tiểu địa phương của hàm lồi là toàn cục", "en": "local minimum equals global minimum for convex functions, uniqueness of minimizer", "kind": "Mệnh đề", "nomna": "Trong cái bát chỉ có một đáy: nếu bạn đứng ở chỗ không thể đi xuống thêm trong vùng gần mình thì đó là đáy thật. Hàm không lồi thì có thể có nhiều “hố nhỏ” khiến bạn kẹt lại.", "short": "Mệnh đề. \\(f\\) lồi trên tập lồi \\(C\\): mọi cực tiểu địa phương là cực tiểu toàn cục; tập các điểm cực tiểu là lồi. Nếu \\(f\\) lồi chặt thì cực tiểu (nếu có) là duy nhất.", "dn": ["Chảo chỉ có một đáy: thấy mình đang ở chỗ “không xuống được nữa” thì đó là đáy thật.", "Đường đi bộ trong công viên phẳng (lồi): xuống dốc đến khi không xuống được là tới chỗ thấp nhất; đồi núi nhiều hố thì có thể kẹt ở hố nhỏ."], "hay": "Đối chiếu: \\(f=x^4-2x^2\\) (không lồi) có hai cực tiểu \\(x=\\pm1\\), \\(f=-1\\) và cực đại địa phương tại \\(0\\) (\\(f=0\\)). \\(f=x^2\\) (lồi) chỉ có một đáy \\(x=0\\)."}, {"id": "bai-toan-chuan", "mod": "m2", "term": "Bài toán tối ưu có ràng buộc (dạng chuẩn)", "en": "constrained optimization, standard form, feasible set, inequality constraints, equality constraints", "kind": "Khái niệm", "nomna": "Bạn muốn làm một việc “tốt nhất có thể” (rẻ nhất, nhiều lãi nhất) nhưng bị giới hạn bởi những luật chơi: ngân sách, thời gian, đẳng thức phải giữ. Dạng chuẩn là cách viết mọi luật chơi theo cùng một khuôn để dùng một công thức giải chung.", "short": "\\(\\min_{x\\in\\mathbb R^n}f(x)\\) s.t. \\(g_i(x)\\le0\\ (i=1..m)\\), \\(h_j(x)=0\\ (j=1..p)\\). Tập khả thi \\(\\Omega=\\{x:g_i\\le0,h_j=0\\}\\). Ràng buộc \\(g\\ge0\\) đổi thành \\(-g\\le0\\); bài max đổi thành \\(\\min(-f)\\). Bài toán là lồi khi \\(f,g_i\\) lồi và \\(h_j\\) afin.", "dn": ["Mua sắm với ngân sách 5 triệu và phải mua đủ 2 món bắt buộc: mục tiêu “thoả mãn nhất”, các giới hạn là ràng buộc.", "Lập thực đơn rẻ nhất mà vẫn đủ 2000 kcal: giá là mục tiêu, kcal ≥ 2000 là ràng buộc."], "hay": "Đề cho Đổi về dạng chuẩn \\(\\max f\\) \\(\\min(-f)\\) \\(g(x)\\ge0\\) \\(-g(x)\\le0\\) \\(x\\ge0\\) \\(-x\\le0\\) \\(a\\le g\\le b\\) \\(g-b\\le0,\\ a-g\\le0\\) Bài: tối đa hoá lợi nhuận \\(10x+8y\\) với \\(x+y\\le100\\), \\(x\\ge0,y\\ge0\\). ① \\(\\min f\\) với \\(f=-(10x+8y)\\). ② \\(g_1=x+y-100\\le0\\), \\(g_2=-x\\le0\\), \\(g_3=-y\\le0\\). ③ \\(f\\) tuyến tính (lồi), \\(g_i\\) afin ⇒ bài toán lồi."}, {"id": "ham-lagrange", "mod": "m2", "term": "Hàm Lagrange và nhân tử", "en": "Lagrangian, Lagrange multiplier, penalty, shadow price, equality constraint", "kind": "Khái niệm", "nomna": "Thay vì cấm bạn vi phạm luật, ta cho phép vi phạm nhưng phải “trả phạt” theo mức vi phạm. Nhân tử Lagrange là mức phạt trên mỗi đơn vị vi phạm — cũng chính là “giá bóng” của ràng buộc.", "short": "\\(L(x,\\lambda,\\mu)=f(x)+\\sum_i\\lambda_ig_i(x)+\\sum_j\\mu_jh_j(x)\\) với \\(\\lambda_i\\ge0\\), \\(\\mu_j\\) tự do. Ràng buộc đẳng thức: \\(\\nabla f+\\mu\\nabla h=0\\) nghĩa là gradient của \\(f\\) song song gradient của \\(h\\) (không thể đi tiếp dọc ràng buộc để giảm \\(f\\)).", "dn": ["Cho phép “vi phạm giới hạn ngân sách nhưng phạt theo mức vượt”: mức phạt mỗi đồng vượt là nhân tử.", "Quán bán thêm giờ làm cho phép tăng ca nhưng trả lương gấp đôi: lương gấp đôi là “giá” của ràng buộc giờ làm."], "hay": "\\(\\min x^2+y^2\\) s.t. \\(x+y=2\\). ① \\(L=x^2+y^2+\\mu(x+y-2)\\). ② \\(L_x=2x+\\mu=0,\\ L_y=2y+\\mu=0\\Rightarrow x=y=-\\mu/2\\). ③ \\(x+y=2\\Rightarrow-\\mu=2\\Rightarrow\\mu=-2\\), \\(x=y=1\\). ④ \\(f=2\\). Ý nghĩa: nếu vế phải 2 đổi thành \\(b\\) thì \\(p^*(b)=b^2/2\\), nên \\(dp^*/db=b=2=-\\mu\\) — nhân tử chính là độ nhạy của giá trị tối ưu theo vế phải."}, {"id": "kkt", "mod": "m2", "term": "Điều kiện Karush–Kuhn–Tucker (bốn mảnh)", "en": "KKT conditions, Karush-Kuhn-Tucker, stationarity, primal feasibility, dual feasibility, complementary slackness", "kind": "Mệnh đề", "nomna": "Bốn điều kiện cùng đúng thì ta đang đứng ở chỗ “hết đường giảm”: (1) lực kéo của hàm mục tiêu bị cân bằng bởi lực chặn của ràng buộc, (2) đang ở trong miền hợp lệ, (3) ràng buộc chỉ “đẩy” chứ không “kéo”, (4) ràng buộc nào không chạm thì không tác dụng lực.", "short": "\\(x^*,\\lambda^*,\\mu^*\\) thoả KKT nếu: ① Dừng : \\(\\nabla f+\\sum\\lambda_i\\nabla g_i+\\sum\\mu_j\\nabla h_j=0\\). ② Khả thi gốc : \\(g_i\\le0,\\ h_j=0\\). ③ Khả thi đối ngẫu : \\(\\lambda_i\\ge0\\). ④ Bù : \\(\\lambda_ig_i=0\\).", "dn": ["Quả bóng lăn trong lòng chảo có tường: ở trạng thái đứng yên, trọng lực kéo xuống bị tường chặn đẩy lại (các lực cân bằng); tường không chạm thì không có lực.", "Cân bằng ngân sách: bạn dừng chi khi giá trị biên của đồng tiền ở mọi hạng mục bằng nhau, hạng mục không dùng tới thì không có “giá”."], "hay": "\\(\\min x^2\\) s.t. \\(1-x\\le0\\). ① Dừng: \\(2x-\\lambda=0\\). ② Bù: \\(\\lambda(1-x)=0\\). Ca \\(\\lambda=0\\): \\(x=0\\), vi phạm \\(1-0\\le0\\) ✘. Ca \\(x=1\\): \\(\\lambda=2\\ge0\\) ✔. Kết luận: \\((x,\\lambda)=(1,2)\\) thoả KKT; bài lồi ⇒ \\(f^*=1\\)."}, {"id": "bu", "mod": "m2", "term": "Điều kiện bù (complementary slackness)", "en": "complementary slackness, active constraint, inactive constraint, binding", "kind": "Mệnh đề", "nomna": "Với mỗi ràng buộc chỉ có hai khả năng: hoặc nó chạm (chặt) và có thể tác dụng lực, hoặc nó còn dư và hoàn toàn không tác dụng. Không có chuyện còn dư mà vẫn kéo.", "short": "\\(\\lambda_ig_i(x^*)=0\\) với mọi i: nếu \\(g_i(x^*) 0\\) thì \\(g_i(x^*)=0\\). Mỗi ràng buộc BĐT có hai ca: \\((\\lambda_i=0)\\) hoặc \\((g_i=0)\\). \\(m\\) ràng buộc ⇒ tối đa \\(2^m\\) ca.", "dn": ["Cửa hàng còn dư nguyên liệu thì “giá bóng” của nguyên liệu bằng 0; chỉ nguyên liệu cạn mới có giá.", "Đèn báo tải: chỉ khi nối dây vào ổ (ràng buộc chạm) đèn mới có dòng điện."], "hay": "Bảng ca (hai ràng buộc): không chặt / chỉ \\(g_1\\) / chỉ \\(g_2\\) / cả hai ⇒ 4 ca. Với mỗi ca giải hệ rồi kiểm: các ràng buộc còn lại khả thi? mọi \\(\\lambda\\ge0\\)?"}, {"id": "chinh-quy", "mod": "m2", "term": "Điều kiện chính quy (LICQ, Slater)", "en": "constraint qualification, LICQ, MFCQ, Slater condition, regularity", "kind": "Khái niệm", "nomna": "KKT đòi hỏi các ràng buộc “không hỏng”: nếu ràng buộc có dạng gấp khúc đặc biệt (ví dụ nhọn như mỏm) thì lực chặn có thể không biểu diễn được. Điều kiện chính quy bảo đảm ràng buộc đủ “hiền” để KKT chắc chắn là điều kiện cần.", "short": "LICQ : gradient các ràng buộc chặt tại \\(x^*\\) độc lập tuyến tính. Slater (bài lồi): tồn tại \\(\\hat x\\) với \\(g_i(\\hat x)", "dn": ["Cái đinh nhọn: nếu hai tường gặp nhau ở một mỏm nhọn quá mức thì bạn không xác định được lực mỗi tường tác dụng — điều kiện chính quy loại trừ các mỏm như vậy.", "Ngân sách đúng bằng chi tiêu tối thiểu: không còn “khoảng trống” để ước lượng giá của ràng buộc."], "hay": "Tình huống Kết luận lồi + KKT đủ cho tối ưu lồi + Slater KKT cần và đủ không lồi + LICQ KKT chỉ cần LICQ vỡ có thể không tồn tại \\(\\lambda\\) Phản ví dụ: \\(\\min x\\) s.t. \\(x^2\\le0\\). ① Miền khả thi chỉ \\(\\{0\\}\\) ⇒ \\(x^*=0\\). ② \\(\\nabla f=1\\), \\(\\nabla g(0)=0\\): dừng cần \\(1+\\lambda\\cdot0=0\\) — vô nghiệm. ③ Slater vỡ: không có \\(x\\) với \\(x^2"}, {"id": "kkt-du", "mod": "m2", "term": "KKT là điều kiện đủ cho bài toán lồi", "en": "sufficiency of KKT for convex problems, global optimality", "kind": "Mệnh đề", "nomna": "Với bài toán “cái bát”, chỉ cần tìm được chỗ lực cân bằng là chắc chắn đã tới đáy thật, không phải “hố giả”.", "short": "Mệnh đề. Nếu \\(f,g_i\\) lồi, \\(h_j\\) afin và \\((x^*,\\lambda^*,\\mu^*)\\) thoả KKT thì \\(x^*\\) là cực tiểu toàn cục .", "dn": ["Chảo lồi: tìm được điểm mà lực cân bằng thì chắc chắn đó là đáy, không cần lo “hố giả”.", "Bài toán thu nhập giảm dần: chỉ cần tìm điểm mà lợi biên cân bằng giữa các hạng mục là xong."], "hay": "\\(\\min(x_1-3)^2+(x_2-2)^2\\) s.t. \\(x_1^2+x_2^2\\le5,\\ x_1+2x_2\\le4\\), điểm \\(\\bar x=(2,1)\\): ① \\(g_1=0,g_2=0\\) (cả hai chặt). ② \\(\\nabla f=(-2,-2)\\), \\(\\nabla g_1=(4,2)\\), \\(\\nabla g_2=(1,2)\\). ③ \\(4\\lambda_1+\\lambda_2=2,\\ 2\\lambda_1+2\\lambda_2=2\\Rightarrow\\lambda=(1/3,2/3)\\ge0\\). ④ Bài lồi ⇒ \\(f^*=1+1=2\\) là cực tiểu toàn cục."}, {"id": "doi-ngau", "mod": "m2", "term": "Hàm đối ngẫu và đối ngẫu yếu/mạnh", "en": "Lagrange dual function, weak duality, strong duality, duality gap, Slater", "kind": "Mệnh đề", "nomna": "Thay vì tìm đáy bát từ trên xuống, ta chọn mức phạt \\(\\lambda\\) rồi tìm giá trị nhỏ nhất của bài “có phạt” — đó luôn là một cận dưới của đáp án thật. Rồi ta chọn \\(\\lambda\\) sao cho cận dưới tốt nhất.", "short": "\\(g(\\lambda)=\\inf_xL(x,\\lambda)\\) (\\(\\lambda\\ge0\\)); \\(g\\) luôn lõm . Đối ngẫu yếu: \\(d^*=\\max_{\\lambda\\ge0}g(\\lambda)\\le p^*\\). Đối ngẫu mạnh \\(d^*=p^*\\) khi lồi + Slater.", "dn": ["Bạn đoán cận dưới cho chi phí tối thiểu bằng cách chọn mức phạt; mức phạt tốt nhất cho cận dưới sát nhất.", "Người thuê và chủ nhà: giá thuê hợp lý là điểm gặp của hai tối ưu hoá."], "hay": "\\(\\min x^2\\) s.t. \\(1-x\\le0\\). ① \\(L=x^2+\\lambda(1-x)\\). ② \\(\\partial_xL=2x-\\lambda=0\\Rightarrow x=\\lambda/2\\). ③ \\(g(\\lambda)=\\lambda^2/4+\\lambda-\\lambda^2/2=\\lambda-\\lambda^2/4\\). ④ \\(g^\\prime=1-\\lambda/2=0\\Rightarrow\\lambda^*=2\\), \\(d^*=g(2)=1\\). ⑤ Gốc: \\(p^*=1\\) ⇒ bằng nhau. Kiểm yếu: \\(g(1)=0.75\\le1\\) ✔."}, {"id": "do-nhay", "mod": "m2", "term": "Ý nghĩa của nhân tử: độ nhạy", "en": "sensitivity analysis, shadow price, marginal value, perturbation", "kind": "Mệnh đề", "nomna": "Nhân tử cho biết nếu nới lỏng ràng buộc thêm một chút thì kết quả tối ưu cải thiện bao nhiêu — như hỏi “thêm 1 giờ máy lời thêm bao nhiêu?”.", "short": "Xét \\(p^*(b)=\\min f\\) s.t. \\(g(x)\\le b\\) (vế phải b là “hạn mức”). Dưới đối ngẫu mạnh và khả vi: \\(\\dfrac{dp^*}{db}=-\\lambda^*\\le0\\): nới hạn mức thêm một đơn vị làm giá trị tối ưu giảm đúng \\(\\lambda^*\\).", "dn": ["Thêm một giờ máy: lợi nhuận tăng thêm bao nhiêu — đó là giá bóng (nhân tử).", "Nâng trần học phí 1 triệu thì quỹ học bổng thay đổi bao nhiêu: tỉ lệ thay đổi chính là nhân tử."], "hay": "\\(\\min x^2\\) s.t. \\(b-x\\le0\\) (tức \\(x\\ge b\\), \\(b>0\\)). ① \\(x^*=b\\), \\(p^*(b)=b^2\\). ② \\(\\lambda^*=2x^*=2b\\) (từ \\(2x-\\lambda=0\\)). ③ \\(dp^*/db=2b=\\lambda^*\\) (ở đây ràng buộc viết là \\(b-x\\le0\\), tăng b là thắt ràng buộc nên \\(p^*\\) tăng đúng \\(\\lambda^*\\)). Số: \\(b=1\\Rightarrow\\lambda=2\\); \\(p^*(1.01)-p^*(1)=0.0201\\approx2\\cdot0.01\\) ✔."}, {"id": "bang-ca", "mod": "m2", "term": "Phép toán: bảng ca KKT", "en": "case analysis, KKT cases, active set enumeration", "kind": "Phép toán", "nomna": "Thử lần lượt từng “kịch bản” xem ràng buộc nào chạm, ràng buộc nào còn dư; kịch bản nào qua được hai bài kiểm tra (khả thi, \\(\\lambda\\ge0\\)) là đáp án.", "short": "Quy trình: (1) chuẩn hoá \\(g\\le0\\); (2) viết hệ KKT; (3) thử cực tiểu tự do; (4) liệt kê ca theo tập chặt; (5) mỗi ca giải hệ rồi kiểm khả thi + \\(\\lambda\\ge0\\).", "dn": ["Thử từng kịch bản “hạng mục nào dùng hết ngân sách”: có hai hạng mục thì thử bốn kịch bản.", "Mở khoá tủ nhiều ổ: thử từng tổ hợp ổ nào đóng, ổ nào mở, kịch bản qua cả hai kiểm tra là đáp án."], "hay": "Bài: \\(\\min(x_1-3)^2+(x_2-2)^2\\) s.t. \\(g_1=x_1^2+x_2^2-5\\le0\\), \\(g_2=x_1+2x_2-4\\le0\\). • Không chặt: \\(x=(3,2)\\): \\(g_1=8>0\\) ✘. • Chỉ \\(g_1\\): \\(x\\approx(1.86,1.24)\\), \\(\\lambda_1\\approx0.61\\); \\(g_2=0.34>0\\) ✘. • Chỉ \\(g_2\\): \\(x=(2.4,0.8)\\), \\(\\lambda_2=1.2\\); \\(g_1=1.4>0\\) ✘. • Cả hai: \\(x=(2,1)\\), \\(\\lambda=(1/3,2/3)\\) ✔ (nghiệm còn lại \\(\\lambda_1"}, {"id": "qp", "mod": "m3", "term": "Quy hoạch toàn phương (QP)", "en": "quadratic programming, QP, quadratic objective, Hessian Q, linear constraints", "kind": "Khái niệm", "nomna": "Giống bài tuyến tính nhưng hàm mục tiêu “cong” (bậc hai): đáy bát thay vì mặt phẳng nghiêng. Ràng buộc vẫn là những bức tường thẳng.", "short": "\\(\\min\\ \\tfrac12x^\\top Qx+c^\\top x\\) s.t. \\(Ax\\le b\\) (có thể thêm \\(A_{eq}x=b_{eq}\\)), \\(Q\\) đối xứng. \\(Q=0\\) ⇒ LP. Hessian của mục tiêu bằng \\(Q\\).", "dn": ["Căng dây cung gần nhất: tìm điểm trong miền “gần” điểm mong muốn nhất (khoảng cách bình phương là hàm bậc hai).", "Điều chỉnh kế hoạch cũ ít nhất có thể để vừa quy định mới: đúng dạng QP."], "hay": "Đưa về dạng chuẩn: \\(f=(x_1-1)^2+(x_2-2.5)^2=x_1^2+x_2^2-2x_1-5x_2+7.25\\). ① \\(\\tfrac12x^\\top Qx=x_1^2+x_2^2\\Rightarrow Q=2I\\). ② \\(c=(-2,-5)\\) (hằng số 7.25 bỏ đi, không đổi nghiệm)."}, {"id": "qp-loi", "mod": "m3", "term": "QP lồi ⇔ Q nửa xác định dương", "en": "convex QP, positive semidefinite Q, strictly convex QP", "kind": "Mệnh đề", "nomna": "Nếu cái “bát” không có hướng nào cong xuống thì bài giải được dễ dàng; chỉ cần nhìn ma trận Q là biết.", "short": "QP lồi ⇔ \\(Q\\succeq0\\) (không phụ thuộc \\(c,A,b\\)). \\(Q\\succ0\\) ⇒ lồi chặt, nghiệm duy nhất nếu miền khả thi khác rỗng. Khi lồi, KKT là điều kiện cần và đủ (ràng buộc afin nên tự chính quy).", "dn": ["Chảo parabol (Q xác định dương): chỉ có một đáy; máng trượt (Q nửa xác định dương): đáy là cả một đường; yên ngựa (Q không xác định): không có đáy.", "Tính phí theo bậc thang tăng dần (lồi): có điểm tối ưu rõ ràng."], "hay": "Q Loại Hệ quả \\(\\mathrm{diag}(2,2)\\) PD lồi chặt, nghiệm duy nhất \\(\\mathrm{diag}(2,0)\\) PSD lồi, có thể nhiều nghiệm hoặc không bị chặn \\(\\mathrm{diag}(2,-2)\\) không xác định không lồi, nhiều cực trị địa phương Q = \\(\\begin{pmatrix}2&1\\\\1&2\\end{pmatrix}\\): \\(D_1=2,D_2=3>0\\) ⇒ PD ⇒ QP lồi chặt."}, {"id": "qp-dang-thuc", "mod": "m3", "term": "QP chỉ có ràng buộc đẳng thức: hệ KKT", "en": "equality constrained quadratic program, KKT system, saddle point system", "kind": "Phép toán", "nomna": "Khi chỉ có ràng buộc “bằng”, bài toán rút về giải một hệ phương trình tuyến tính — không cần thử ca.", "short": "\\(\\min\\tfrac12x^\\top Qx+c^\\top x\\) s.t. \\(Ax=b\\). Điều kiện cần: \\(\\begin{pmatrix}Q&A^\\top\\\\A&0\\end{pmatrix}\\begin{pmatrix}x\\\\\\mu\\end{pmatrix}=\\begin{pmatrix}-c\\\\b\\end{pmatrix}\\). Ma trận KKT khả nghịch nếu A đủ hạng hàng và \\(Z^\\top QZ\\succ0\\) (Z: cơ sở của \\", "dn": ["Chia một khoản tiền cố định cho nhiều hạng mục để tổng bình phương “mức chênh” nhỏ nhất: chỉ cần giải hệ phương trình.", "Cân bằng nhiều cột chịu lực với tổng tải cố định: giải một hệ tuyến tính."], "hay": "\\(\\min x_1^2+x_2^2+x_3^2-2x_1-5x_2\\) s.t. \\(x_1+x_2+x_3=3\\). ① \\(Q=2I,\\ c=(-2,-5,0),\\ A=(1\\,1\\,1),\\ b=3\\). ② \\(2x_1-2+\\mu=0\\Rightarrow x_1=(2-\\mu)/2\\); \\(x_2=(5-\\mu)/2\\); \\(x_3=-\\mu/2\\). ③ Cộng: \\(7/2-3\\mu/2=3\\Rightarrow\\mu=1/3\\). ④ \\(x^*=(5/6,\\ 7/3,\\ -1/6)\\), \\(f^*=-43/6\\approx-7.167\\)."}, {"id": "null-space", "mod": "m3", "term": "Phương pháp không gian null", "en": "null space method, reduced Hessian, elimination of constraints, basis of kernel", "kind": "Phép toán", "nomna": "Thay vì “cấm” đi ra ngoài ràng buộc, ta đặt lại toạ độ sao cho mọi bước đi đều nằm trong ràng buộc sẵn — rồi giải bài không ràng buộc nhỏ hơn.", "short": "Chọn \\(x_p\\) với \\(Ax_p=b\\) và \\(Z\\) có các cột là cơ sở của \\(\\ker A\\). Mọi nghiệm khả thi có dạng \\(x=x_p+Zy\\). Bài rút gọn: \\(\\min_y\\tfrac12y^\\top(Z^\\top QZ)y+(Qx_p+c)^\\top Zy\\); nghiệm \\(Z^\\top QZ\\,y=-Z^\\top(Qx_p+c)\\).", "dn": ["Đi trên một mặt phẳng cố định: chỉ cần chọn toạ độ trên mặt đó (hướng nằm trong mặt) chứ không cần để ý hướng ra khỏi mặt.", "Chuyển tiền giữa các khoản mà tổng không đổi: chỉ có các “hướng chuyển” hợp lệ (cộng một khoản, trừ khoản khác) là tự do."], "hay": "Cùng bài ở trên: \\(x_p=(3,0,0)\\), \\(Z=\\begin{pmatrix}-1&-1\\\\1&0\\\\0&1\\end{pmatrix}\\). ① \\(Z^\\top QZ=\\begin{pmatrix}4&2\\\\2&4\\end{pmatrix}\\succ0\\). ② \\(Qx_p+c=(6,0,0)+(-2,-5,0)=(4,-5,0)\\); \\(Z^\\top(4,-5,0)=(-4-5,\\ -4)=(-9,-4)\\) ⇒ vế phải \\(-Z^\\top(\\cdot)=(9,4)\\). ③ \\(\\begin{pmatrix}4&2\\\\2&4\\end{pmatrix}y=(9,4)\\Rightarrow y=(7/3,-1/6)\\). ④ \\(x=x_p+Zy=(3-7/3+1/6,\\ 7/3,\\ -1/6)=(5/6,7/3,-1/6)\\) ✔ khớp hệ KKT."}, {"id": "ton-tai", "mod": "m3", "term": "Tồn tại nghiệm của QP (Frank–Wolfe)", "en": "existence of solution, Frank-Wolfe theorem, recession direction, unbounded below", "kind": "Mệnh đề", "nomna": "Đường đi xuống có thể “không có đáy”. Với QP có một mẹo hay: nếu hàm không rơi xuống vô tận thì chắc chắn có đáy thật, không bao giờ chỉ “tiến sát mà không chạm”.", "short": "Định lý Frank–Wolfe. QP bị chặn dưới trên một đa diện khác rỗng thì đạt cực tiểu (kể cả khi không lồi). Không bị chặn dưới nếu tồn tại hướng lùi xa \\(d\\) (\\(Ad\\le0\\)) với \\(d^\\top Qd", "dn": ["Cầu trượt dốc vô tận: có thể trượt mãi, không có chỗ thấp nhất; nếu dốc chỉ xuống rồi lại lên thì có đáy.", "Lãi “vô hạn” trên giấy báo hiệu mô hình sai chứ không phải cơ hội thật."], "hay": "Tình huống Kết luận miền rỗng vô nghiệm miền bị chặn có nghiệm \\(Q\\succ0\\) nghiệm duy nhất hướng lùi xa với \\(d^\\top Qd không bị chặn dưới \\(\\min-x_1^2+x_2\\) s.t. \\(x\\ge0\\). ① Hướng lùi xa \\(d=(1,0)\\): \\(Ad=-d\\le0\\) ✔. ② \\(d^\\top Qd\\), \\(Q=\\mathrm{diag}(-2,0)\\): \\(=-2 ③ \\(f(t,0)=-t^2\\to-\\infty\\) (t=10: −100; t=100: −10000) ⇒ không bị chặn dưới, không có nghiệm."}, {"id": "active-set", "mod": "m3", "term": "Thuật toán tập hoạt động (active set)", "en": "active set method, working set, quadratic programming algorithm, constraint activation", "kind": "Phép toán", "nomna": "Hãy coi các ràng buộc “đang chạm” như những bức tường mà ta đang dựa vào. Ta giả sử một nhóm tường (tập làm việc W) là chặt, tìm hướng đi tốt nhất dọc theo các tường đó, và mỗi vòng chỉ thay đổi nhiều nhất một bức tường.", "short": "Tại \\(x_k\\) với tập làm việc \\(W\\): giải \\(\\begin{pmatrix}Q&A_W^\\top\\\\A_W&0\\end{pmatrix}\\begin{pmatrix}d\\\\\\mu\\end{pmatrix}=\\begin{pmatrix}-g\\\\0\\end{pmatrix}\\), \\(g=Qx_k+c\\). (a) \\(d=0\\) và mọi \\(\\mu\\ge0\\): dừng . (b) \\(d=0\\) có \\(\\mu_j", "dn": ["Đi dọc các bức tường đang chạm cho đến khi gặp tường mới (thêm) hoặc nhận ra mình tựa nhầm tường (bỏ).", "Điều khiển xe trong làn đường: bám sát vạch kẻ khi cần (ràng buộc chạm), rời vạch khi có thể đi tốt hơn."], "hay": "Tình huống Hành động \\(d=0,\\ \\mu\\ge0\\) dừng, tối ưu \\(d=0,\\ \\mu_j bỏ ràng buộc \\(j\\) \\(d\\ne0,\\ \\alpha thêm ràng buộc cản \\(d\\ne0,\\ \\alpha=1\\) bước đầy, không đổi W Ví dụ (\\(x_0=(2,0)\\), \\(W_0=\\{3,5\\}\\)): k=0 : \\(d=0\\), \\(\\mu=(-2,-1)\\) ⇒ bỏ ràng buộc 3. k=1 : \\(W=\\{5\\}\\), \\(d=(-1,0)\\), \\(\\alpha=1\\) ⇒ \\(x=(1,0)\\). k=2 : \\(d=0\\), \\(\\mu=-5\\) ⇒ bỏ 5. k=3 : \\(W=\\emptyset\\), \\(d=(0,2.5)\\), \\(\\alpha=0.6\\) bị cản bởi (1) ⇒ \\(x=(1,1.5)\\), thêm (1). k=4 : \\(d=(0.4,0.2)\\), \\(\\alpha=1\\) ⇒ \\(x=(1.4,1.7)\\). k=5 : \\(d=0\\), \\(\\mu=0.8\\ge0\\) ⇒ dừng; \\(f^*=0.8\\)."}, {"id": "buoc-alpha", "mod": "m3", "term": "Độ dài bước α và ràng buộc cản", "en": "step length, blocking constraint, ratio test, line search with constraints", "kind": "Phép toán", "nomna": "Bạn muốn đi hết quãng đường đã tính, nhưng có thể đâm vào một bức tường khác trước khi tới đích — khi đó dừng ngay tại tường và coi nó là tường mới.", "short": "\\(\\alpha=\\min\\Big\\{1,\\ \\min_{i\\notin W,\\ a_i^\\top d>0}\\dfrac{b_i-a_i^\\top x}{a_i^\\top d}\\Big\\}\\). Chỉ xét ràng buộc ngoài W và có \\(a_i^\\top d>0\\) (đang tiến sát tường). \\(\\alpha", "dn": ["Xe đi theo lộ trình nhưng phải dừng ở vạch giới hạn đầu tiên gặp.", "Rót nước vào ly: dừng khi chạm vạch trên cùng dù định rót thêm."], "hay": "Tại \\(x=(1,0)\\), \\(d=(0,2.5)\\), ràng buộc (1): \\(-x_1+2x_2\\le2\\). ① \\(a^\\top d=2\\cdot2.5=5>0\\). ② Độ dư: \\(b-a^\\top x=2-(-1)=3\\). ③ Tỉ số \\(=3/5=0.6\\); các ràng buộc khác: (2) \\(1\\cdot0+2\\cdot2.5=5>0\\), dư \\(6-1=5\\Rightarrow1\\); lấy \\(\\min\\{1,0.6,1\\}=0.6\\). ④ \\(x_{\\text{mới}}=(1,0)+0.6\\cdot(0,2.5)=(1,1.5)\\)."}, {"id": "mu-am", "mod": "m3", "term": "Nhân tử âm: vì sao phải bỏ ràng buộc", "en": "negative multiplier, dropping constraint, constraint release", "kind": "Mệnh đề", "nomna": "Nhân tử âm nghĩa là bức tường đang “kéo” bạn lại thay vì đẩy: bạn đang tựa nhầm tường, rời khỏi nó sẽ đi xuống tiếp được.", "short": "Tại \\(x\\) với \\(d=0\\) và \\(\\mu_j", "dn": ["Tựa vào tường mà tường “kéo” bạn lại: thả tay khỏi tường là đi tiếp xuống được.", "Hạn mức giá âm: bỏ hạn mức đó làm kết quả tốt hơn."], "hay": "Ở k=0: \\(x_0=(2,0)\\), \\(g=Qx+c=(4-2,\\ 0-5)=(2,-5)\\), W={3,5}: \\(\\mu=(-2,-1)\\). Bỏ ràng buộc 3 (\\(\\mu\\) âm nhất) ⇒ giải lại với W={5} cho hướng \\(d=(-1,0)\\): \\(f\\) giảm từ \\(f(2,0)=7.25\\) xuống \\(f(1,0)=6.25\\)."}, {"id": "loi-tat-kkt", "mod": "m4", "term": "Lối tắt rút gọn bảng ca KKT", "en": "shortcut for KKT, unconstrained minimizer first, eliminate equality, case pruning", "kind": "Phép toán", "nomna": "Trước khi liệt kê mọi kịch bản, hỏi hai câu rẻ: “đáy tự do có nằm trong miền không?” và “có thể thế bớt một ẩn không?”. Phần lớn bài thi chỉ còn 1–2 ca.", "short": "(1) Nếu cực tiểu không ràng buộc \\(x_0\\) khả thi thì \\(x_0\\) là nghiệm và mọi \\(\\lambda=0\\). (2) Với \\(h(x)=0\\) tuyến tính, rút một biến, thế vào \\(f\\) và \\(g\\). (3) Giải \\(x,y\\) theo một tham số \\(\\lambda\\) rồi dùng \\(\\lambda g=0\\). (4) Loại ca có \\(\\lambda", "dn": ["Muốn tìm quán ăn rẻ nhất trong khu: trước hết hỏi “quán rẻ nhất cả thành phố có nằm trong khu không?” Nếu có thì xong, khỏi duyệt từng quán.", "Bỏ bớt một ẩn bằng cách thế vào: như dùng “tổng bằng 10” để chỉ còn tìm một số."], "hay": "Lối tắt Bài ví dụ Kết quả cực tiểu tự do \\(\\min(x-3)^2+(y-4)^2-2,\\ x^2+y^2\\le36\\) \\((3,4)\\), \\(f^*=-2\\) khử đẳng thức \\(\\min(x-1)^2+y-2,\\ y=x+1,\\ x+y\\le2\\) \\(x^2-x,\\ x\\le\\tfrac12\\) theo \\(\\lambda\\) bài B \\(x=\\tfrac12-\\lambda,\\ g=-2\\lambda\\) Bài A, R=4: \\(\\min(x-3)^2+(y-4)^2-2\\) s.t. \\(x^2+y^2\\le16\\). ① Cực tiểu tự do \\((3,4)\\): \\(25>16\\) ✘ (không dùng được lối tắt 1). ② Giả sử \\(g\\) chặt: \\(x(1+\\lambda)=3,\\ y(1+\\lambda)=4\\). ③ \\(x^2+y^2=\\tfrac{25}{(1+\\lambda)^2}=16\\Rightarrow1+\\lambda=\\tfrac54\\Rightarrow\\lambda=\\tfrac14\\). ④ \\((x,y)=(2.4,3.2)\\), \\(f^*=-1\\)."}, {"id": "suy-bien", "mod": "m4", "term": "Ràng buộc chặt nhưng nhân tử bằng 0 (suy biến)", "en": "degenerate KKT point, strict complementarity, active constraint with zero multiplier", "kind": "Mệnh đề", "nomna": "Bạn đứng ngay sát vạch giới hạn nhưng không cần dựa vào nó: vạch chạm mà không “đẩy” bạn.", "short": "Tại điểm KKT có thể có \\(g_i(x^*)=0\\) và \\(\\lambda_i=0\\). Điều kiện bù \\(\\lambda_ig_i=0\\) vẫn thoả. Gọi là suy biến (không có bù chặt). Ví dụ bài B: \\(g=0\\) tại \\((\\tfrac12,\\tfrac32)\\) với \\(\\lambda=0\\).", "dn": ["Bạn đứng đúng sát mép vạch giới hạn tốc độ nhưng không cần đạp phanh: vạch “chạm” mà không tác dụng lực.", "Quỹ ngân sách vừa đủ vào lúc chi tiêu tối ưu: giới hạn chạm mà “giá bóng” bằng 0."], "hay": "Bài B: \\(\\lambda=0\\Rightarrow x=\\tfrac12-\\lambda=\\tfrac12\\), \\(y=\\tfrac32\\), \\(g=-2\\lambda=0\\). Ràng buộc chặt (\\(g=0\\)) nhưng \\(\\lambda=0\\). Giải thích hình học: bài khử \\(f=x^2-x\\) có đỉnh \\(x=\\tfrac12\\) đúng ở biên \\(x\\le\\tfrac12\\)."}, {"id": "kkt-khong-loi", "mod": "m4", "term": "Điểm KKT trong bài không lồi", "en": "KKT for nonconvex problems, necessary but not sufficient, saddle, local maximum", "kind": "Mệnh đề", "nomna": "Cân bằng chưa chắc là đáy: đỉnh đồi cũng cân bằng.", "short": "Với bài không lồi, KKT chỉ là điều kiện cần (dưới điều kiện chính quy). Có thể có điểm KKT là cực đại hoặc yên ngựa. Cách xử lý: liệt kê mọi điểm KKT rồi so giá trị , hoặc xét cấp hai trên hướng cho phép.", "dn": ["Dừng xe ở đỉnh đồi vì “không còn dốc” cũng là một điểm cân bằng, nhưng đó không phải chỗ thấp nhất.", "Cân bằng cây bút trên đầu ngón tay: cân bằng thật nhưng không bền."], "hay": "Bài Điểm KKT Giá trị Loại \\(\\min-x^2,\\ x^2\\le1\\) \\(x=0\\) 0 cực đại \\(x=\\pm1\\) −1 cực tiểu \\(L=-x^2+\\lambda(x^2-1)\\): ① \\(\\partial_xL=-2x+2\\lambda x=0\\Rightarrow x(\\lambda-1)=0\\). ② \\(\\lambda=0\\Rightarrow x=0,\\ g=-1\\le0\\) ✔: KKT, \\(f=0\\). ③ \\(g=0\\Rightarrow x=\\pm1,\\ \\lambda=1\\ge0\\) ✔: KKT, \\(f=-1\\). ④ So giá trị: \\(-1"}, {"id": "d4-minimax", "mod": "d4", "term": "Bất đẳng thức minimax", "en": "minimax inequality, sup inf, inf sup, saddle point, game value", "kind": "Mệnh đề", "nomna": "Trong một ván chơi hai người, người đi sau luôn có lợi thế hơn hoặc bằng người đi trước. “Max của min” (X đi trước) không bao giờ vượt “min của max” (Y đi trước).", "short": "\\(\\sup_{x\\in C}\\inf_{y\\in D}f(x,y)\\le\\inf_{y\\in D}\\sup_{x\\in C}f(x,y)\\) với mọi \\(f:C\\times D\\to[-\\infty,\\infty]\\). Nếu có điểm yên ngựa \\((x_0,y_0)\\) thì dấu bằng xảy ra.", "dn": ["Hai người chơi nối tiếp: người đi sau luôn thấy rõ nước đi của người trước nên không bao giờ tệ hơn.", "Chọn giá trước hay sau đối thủ: đặt sau biết giá đối thủ nên lợi thế hơn hoặc bằng."], "hay": "Trò chơi \\(\\sup\\inf\\) \\(\\inf\\sup\\) Yên ngựa? \\(f=(x-y)^2\\) trên \\(\\{0,1\\}^2\\) 0 1 không \\(f=4-3x-2y+4xy\\) trên \\([0,1]^2\\) 2.5 2.5 có \\((0.5,0.75)\\) \\(f=(x-y)^2\\), \\(x,y\\in\\{0,1\\}\\). \\(\\inf_y f(x,y)=0\\) (chọn \\(y=x\\)) ⇒ \\(\\sup\\inf=0\\). \\(\\sup_xf(x,y)=1\\) (chọn \\(x\\ne y\\)) ⇒ \\(\\inf\\sup=1\\). \\(0"}, {"id": "d4-yen-ngua", "mod": "d4", "term": "Điểm yên ngựa của hàm Lagrange", "en": "saddle point, Lagrangian saddle, min-max point", "kind": "Khái niệm", "nomna": "Điểm “yên ngựa” là chỗ vừa là đáy theo hướng này, vừa là đỉnh theo hướng kia: bạn (người chọn x) muốn xuống thấp, đối thủ (chọn λ) muốn lên cao, và không ai muốn đổi nước đi.", "short": "\\((\\bar x,\\bar\\lambda)\\) là điểm yên ngựa của \\(L\\) nếu \\(L(\\bar x,\\lambda)\\le L(\\bar x,\\bar\\lambda)\\le L(x,\\bar\\lambda)\\) với mọi \\(x\\in\\Theta,\\lambda\\ge0\\). Khi đó \\(\\bar x\\) tối ưu gốc, \\(\\bar\\lambda\\) tối ưu đối ngẫu và \\(p=d\\).", "dn": ["Yên ngựa cưỡi: đi dọc lưng ngựa thì lên cao nhất ở giữa, đi ngang theo bụng thì thấp nhất ở giữa.", "Hai người cầm hai đầu dây co giãn: một bên kéo, một bên thả; cân bằng khi không bên nào muốn thay đổi."], "hay": "Bài Điểm yên ngựa Giá trị \\(\\min x^2,\\ x\\le1\\) \\((0,0)\\) 0 \\(\\min x^2+y^2,\\ x+y\\ge2\\) \\((1,1;\\lambda=2)\\) 2 \\(L=x^2+\\lambda(x-1)\\): \\(L(x,0)=x^2\\ge0=L(0,0)\\) ✔ (min theo x); \\(L(0,\\lambda)=-\\lambda\\le0=L(0,0)\\) ✔ (max theo λ≥0)."}, {"id": "d4-ham-doi-ngau", "mod": "d4", "term": "Hàm đối ngẫu Lagrange", "en": "Lagrange dual function, dual problem, lower bound, concave dual function", "kind": "Khái niệm", "nomna": "Mỗi bảng giá phạt \\(\\lambda\\) cho một chặn dưới của chi phí thật: “dù bạn khéo thế nào, chi phí không thể thấp hơn mức này”. Hàm đối ngẫu cho biết chặn dưới tốt nhất ứng với mỗi bảng giá.", "short": "\\(\\hat L(\\lambda)=\\inf_{x\\in\\Theta}L(x,\\lambda)\\), \\(\\lambda\\ge0\\). Luôn lõm; \\(\\hat L(\\lambda)\\le p\\) với mọi \\(\\lambda\\ge0\\).", "dn": ["Thuê một người kiểm toán đặt giá phạt cho từng điều kiện: giá nào cũng cho bạn một chặn dưới về chi phí.", "Thang điểm “chặn dưới”: mỗi giám khảo cho một mức điểm tối thiểu bạn chắc chắn đạt; điểm cao nhất trong các mức đó là chặn tốt nhất."], "hay": "Bài gốc \\(\\hat L(\\lambda)\\) \\(\\min x^2,\\ x\\le1\\) \\(-\\tfrac14\\lambda^2-\\lambda\\) \\(\\min x_1^2+x_2^2,\\ x_1+x_2\\ge2\\) \\(2\\lambda-\\tfrac12\\lambda^2\\) LP \\(\\min c^\\top x,\\ Ax=b,\\ x\\ge0\\) \\(b^\\top\\mu\\) nếu \\(A^\\top\\mu\\le c\\), \\(-\\infty\\) nếu không \\(\\min x^2\\), \\(x\\le1\\): \\(L=x^2+\\lambda(x-1)\\); \\(\\partial_x:\\ x=-\\tfrac\\lambda2\\); \\(\\hat L=\\tfrac{\\lambda^2}4-\\tfrac{\\lambda^2}2-\\lambda=-\\tfrac{\\lambda^2}4-\\lambda\\). Tại \\(\\lambda=2\\): \\(-1-2=-3\\le0=p\\) ✔."}, {"id": "d4-doi-ngau-yeu-manh", "mod": "d4", "term": "Đối ngẫu yếu và đối ngẫu mạnh", "en": "weak duality, strong duality, duality gap, zero duality gap", "kind": "Mệnh đề", "nomna": "Yếu: chặn dưới không bao giờ vượt quá chi phí thật. Mạnh: chặn dưới tốt nhất chạm chi phí thật — không còn khe hở.", "short": "Yếu : \\(d\\le p\\) (luôn đúng). Mạnh : \\(p=d\\) — đúng khi KKT thoả tại \\((\\bar x,\\bar\\lambda)\\), hoặc với bài lồi có Slater, hoặc với LP khả thi và hữu hạn.", "dn": ["Giá niêm yết của người bán không bao giờ thấp hơn giá nhập tối thiểu (yếu); hai giá bằng nhau là thị trường hiệu quả (mạnh).", "Cận dưới của bạn luôn ≤ giá trị thật; khi chúng bằng nhau không còn khe hở."], "hay": "Loại Điều kiện Kết luận yếu không cần gì \\(d\\le p\\) mạnh (KKT) KKT tại \\((\\bar x,\\bar\\lambda)\\) \\(p=d\\), \\(\\bar x\\) tối ưu mạnh (LP) LP khả thi, giá trị hữu hạn \\(p=d\\) Bài \\(\\min x^2,\\ x\\le1\\): \\(\\bar x=0,\\bar\\lambda=0\\) thoả KKT (\\(2\\cdot0+0=0\\), \\(\\bar\\lambda g=0\\)) ⇒ \\(p=d=0\\)."}, {"id": "d4-doi-ngau-lp", "mod": "d4", "term": "Lập đối ngẫu LP bằng bảng quy tắc dấu", "en": "LP duality, dual of linear program, sign convention table, transposition rule", "kind": "Phép toán", "nomna": "Mỗi “điều kiện” của bài gốc trở thành một “giá” của bài đối ngẫu; mỗi “biến” của bài gốc trở thành một “điều kiện” của bài đối ngẫu. Dấu ≥, =, ≤ quyết định dấu của giá.", "short": "Gốc min: hàng “≥” ↔ \\(y\\ge0\\); “=” ↔ tự do; “≤” ↔ \\(y\\le0\\). Cột \\(x\\ge0\\) ↔ \\(A^\\top y\\le c\\); tự do ↔ “=”; \\(x\\le0\\) ↔ “≥”. Mục tiêu đối ngẫu \\(\\max b^\\top y\\).", "dn": ["Chủ xưởng muốn chi phí nhỏ nhất, người định giá muốn doanh thu lớn nhất; hai bên gặp nhau tại một con số.", "Bảng quy đổi như đổi sang tiền tệ khác: ≥ ↔ ≥0, = ↔ tự do, ≤ ↔ ≤0."], "hay": "Gốc (min) Đối ngẫu (max) hàng “≥” \\(y_i\\ge0\\) hàng “=” \\(y_i\\) tự do hàng “≤” \\(y_i\\le0\\) \\(x_j\\ge0\\) \\(\\sum a_{ij}y_i\\le c_j\\) \\(x_j\\) tự do \\(\\sum a_{ij}y_i=c_j\\) \\(x_j\\le0\\) \\(\\sum a_{ij}y_i\\ge c_j\\) \\(\\min5x_1+4x_2\\) s.t. \\(x_1+2x_2\\ge6,\\ 3x_1+x_2\\ge8,\\ x\\ge0\\): hai hàng “≥” ⇒ \\(y\\ge0\\); hai cột \\(x\\ge0\\) ⇒ hai ràng buộc “≤”: \\(y_1+3y_2\\le5\\), \\(2y_1+y_2\\le4\\); \\(\\max6y_1+8y_2\\). Giá trị \\(18=18\\)."}, {"id": "d4-do-lech-bu", "mod": "d4", "term": "Độ lệch bù (complementary slackness)", "en": "complementary slackness, complementarity condition, strict complementarity", "kind": "Mệnh đề", "nomna": "Hai bên không thể cùng “dư”: nếu ràng buộc gốc còn dư thì giá của nó bằng 0; nếu giá của nó dương thì ràng buộc phải dùng hết. Cũng đúng từ phía biến.", "short": "Cặp khả thi \\((x,y)\\) tối ưu ⇔ \\(y_i(a_i^\\top x-b_i)=0\\ \\forall i\\) và \\(x_j(c_j-a_j^\\top y)=0\\ \\forall j\\).", "dn": ["Thùng hàng còn trống chỗ thì không cần trả phụ phí kho; phụ phí dương nghĩa là kho đã chật.", "Nếu bạn sản xuất một mặt hàng thì giá trị nguyên liệu dùng cho nó đúng bằng lợi nhuận của nó."], "hay": "Điều kiện Hệ quả \\(y_i>0\\) ràng buộc gốc i chặt ràng buộc gốc i lỏng \\(y_i=0\\) \\(x_j>0\\) ràng buộc đối ngẫu j chặt ràng buộc đối ngẫu j lỏng \\(x_j=0\\) Gốc \\(\\min5x_1+4x_2\\), nghiệm \\(x=(2,2)\\): cả hai ràng buộc chặt (\\(2+4=6\\), \\(6+2=8\\)) — không ép \\(y\\)=0; \\(x_1,x_2>0\\) ⇒ hai ràng buộc đối ngẫu chặt: \\(y_1+3y_2=5\\), \\(2y_1+y_2=4\\Rightarrow y=(1.4,1.2)\\)."}, {"id": "d4-4-truong-hop", "mod": "d4", "term": "Bốn khả năng của cặp gốc–đối ngẫu", "en": "primal dual outcomes, unbounded, infeasible, strong duality LP", "kind": "Mệnh đề", "nomna": "Hai bài như hai bên cầu: hoặc cùng chạm nhau (tối ưu), hoặc một bên “bay lên trời” thì bên kia không có chỗ đặt chân, hoặc cả hai đều trống.", "short": "Với LP: (i) cả hai tối ưu, \\(f^*=g^*\\); (ii) gốc không bị chặn ⇒ đối ngẫu vô nghiệm; (iii) đối ngẫu không bị chặn ⇒ gốc vô nghiệm; (iv) cả hai vô nghiệm. Không có trường hợp “một bài tối ưu hữu hạn, bài kia vô nghiệm”.", "dn": ["Một bên trống thì bên kia hoặc cũng trống hoặc “vươn vô tận” — không bao giờ có chuyện một bên hữu hạn mà bên kia trống.", "Lợi nhuận tăng vô hạn không thể được “biện minh” bởi bất kỳ bảng giá nào."], "hay": "Gốc Đối ngẫu Ví dụ tối ưu tối ưu \\(\\min5x_1+4x_2,\\dots\\) không bị chặn vô nghiệm \\(\\min-x,\\ x\\ge0\\) vô nghiệm không bị chặn đối ngẫu của dòng trên vô nghiệm vô nghiệm \\(x_1+x_2\\le-1,\\ x\\ge0\\) và ràng buộc đối ngẫu mâu thuẫn \\(\\min-x\\) s.t. \\(x\\ge0\\): gốc không bị chặn (\\(x\\to\\infty\\)). Đối ngẫu \\(\\max0\\cdot y\\) s.t. \\(y\\le-1\\) (từ \\(A^\\top y\\le c\\) với \\(A=1\\), \\(c=-1\\), \\(y\\ge0\\)): vô nghiệm ✔."}, {"id": "d4-svm-doi-ngau", "mod": "d4", "term": "Đối ngẫu của SVM", "en": "SVM dual, support vectors, Gram matrix, kernel trick, maximum margin", "kind": "Phép toán", "nomna": "Thay vì tìm trực tiếp mặt phẳng phân loại, ta tìm “trọng số” của từng điểm dữ liệu; mặt phẳng là tổ hợp có trọng số của các điểm trên lề (vectơ hỗ trợ).", "short": "\\(\\min\\tfrac12\\lVert w\\rVert^2\\) s.t. \\(y_i\\langle w,x_i\\rangle\\ge1\\) có đối ngẫu \\(\\max-\\tfrac12\\lambda^\\top Q\\lambda+e^\\top\\lambda\\), \\(\\lambda\\ge0\\), \\(Q_{ij}=y_iy_j\\langle x_i,x_j\\rangle\\); nghiệm gốc \\(w=\\sum\\lambda_iy_ix_i\\).", "dn": ["Hàng rào giữa hai làng chỉ cần dựa vào vài ngôi nhà sát ranh giới; các nhà xa không ảnh hưởng.", "Bỏ phiếu có trọng số: chỉ những cử tri “sát nút” mới có trọng số dương."], "hay": "Gốc Đối ngẫu ẩn \\(w\\) (có thể vô hạn chiều) ẩn \\(\\lambda\\in\\mathbb R^m\\) ràng buộc affine theo w ràng buộc dấu \\(\\lambda\\ge0\\) dữ liệu xuất hiện bất kỳ chỉ qua \\(\\langle x_i,x_j\\rangle\\) (kernel) \\(x_1=(0,1,1),x_2=(1,0,1),y=(1,-1)\\): \\(\\min\\lambda_1^2+\\lambda_2^2-\\lambda_1\\lambda_2-\\lambda_1-\\lambda_2\\) ⇒ \\(\\lambda=(1,1)\\); \\(\\bar w=(-1,1,0)\\); lề \\(\\sqrt2\\)."}, {"id": "d4-fenchel", "mod": "d4", "term": "Liên hợp Fenchel", "en": "Fenchel conjugate, convex conjugate, Legendre transform, Fenchel-Young inequality", "kind": "Khái niệm", "nomna": "Với mỗi độ dốc v, hãy trượt một đường thẳng dốc v từ dưới lên cho đến khi chạm đồ thị; điểm cắt trục tung (đổi dấu) là f*(v). Liên hợp “nhớ” mọi đường tựa của hàm.", "short": "\\(f^*(v)=\\sup_x\\{\\langle v,x\\rangle-f(x)\\}\\); luôn lồi; Fenchel–Young \\(\\langle v,x\\rangle\\le f(x)+f^*(v)\\), dấu bằng ⇔ \\(v\\in\\partial f(x)\\).", "dn": ["Dựng tường tựa vào đồ thị: với mỗi độ nghiêng v, tường cao nhất còn nằm dưới đồ thị cho bạn f*(v).", "Đổi cách mô tả đường cong: thay vì “độ cao tại mỗi vị trí” (f), dùng “độ cao gốc của tiếp tuyến theo mỗi độ dốc” (f*)."], "hay": "\\(f\\) \\(f^*\\) \\(x^2\\) \\(v^2/4\\) \\(\\tfrac12x^2\\) \\(\\tfrac12v^2\\) \\(\\lVert x\\rVert\\) \\(0\\) nếu \\(\\lVert v\\rVert\\le1\\), \\(+\\infty\\) nếu ngược lại \\(e^x\\) \\(v\\ln v-v\\ (v>0)\\) \\(f=x^2\\): \\(\\sup_x(vx-x^2)\\) tại \\(x=v/2\\): \\(f^*=v^2/2-v^2/4=v^2/4\\). Với \\(v=2\\): \\(f^*(2)=1\\). Fenchel–Young tại \\(x=1\\): \\(f(1)+f^*(2)=1+1=2=2\\cdot1\\) ✔ dấu bằng (vì \\(2=f^\\prime(1)\\))."}, {"id": "d5-gia-bong", "mod": "d5", "term": "Giá bóng (shadow price)", "en": "shadow price, marginal value, dual variable, sensitivity, resource allocation", "kind": "Khái niệm", "nomna": "Giá bóng cho biết “một đơn vị tài nguyên thêm đáng giá bao nhiêu”. Nếu người bán chào giá cao hơn giá bóng thì đừng mua.", "short": "Với LP, nghiệm đối ngẫu \\(y_i^*\\) là mức tăng biên của giá trị tối ưu khi tăng \\(b_i\\) một đơn vị, chừng nào cơ sở tối ưu không đổi: \\(\\partial p^*/\\partial b_i=y_i^*\\). Tổng quát (bài min, \\(g_i\\le b_i\\)): \\(\\partial v/\\partial b_i=-\\lambda_i^*\\).", "dn": ["Thêm một giờ máy làm tăng lợi nhuận một khoản cố định: khoản đó là giá bóng của giờ máy.", "Nhà cung cấp chào giá cao hơn giá bóng thì từ chối."], "hay": "\\(b_2\\) 4 5 6 8 9 \\(p^*\\) (LP ví dụ) 8 9 10 12 12 \\(\\max3x_1+2x_2\\), \\(x_1+x_2\\le4\\), \\(2x_1+x_2\\le b_2\\). \\(y^*=(1,1)\\). \\(b_2:5\\to6\\): \\(p^*:9\\to10\\) (tăng \\(y_2=1\\)). Hiệu lực trong \\([4,8]\\); ở \\(b_2=9\\) giá bóng thành 0."}, {"id": "d5-ham-q", "mod": "d5", "term": "Hàm đối ngẫu q và tính lõm", "en": "Lagrange dual function, concave, infimum of affine functions, lower bound", "kind": "Khái niệm", "nomna": "Mỗi bộ nhân tử cho một “mức sàn” cho giá trị tối ưu; q là mức sàn tốt nhất bạn có thể dựng với bộ nhân tử đó.", "short": "\\(q(\\lambda,\\nu)=\\inf_xL(x,\\lambda,\\nu)\\), \\(\\lambda\\ge0\\). \\(q\\) lõm kể cả khi gốc không lồi; với \\(x\\) khả thi, \\(q\\le L\\le f(x)\\); suy ra \\(d^*=\\sup q\\le p^*\\).", "dn": ["Mỗi lựa chọn giá phạt cho một mức sàn; tìm mức sàn cao nhất.", "Dự toán công trình: mọi bản dự toán hợp lệ đều thấp hơn hoặc bằng chi phí thật."], "hay": "Bài \\(q\\) \\(\\lambda^*\\) \\(d^*\\) \\(\\min x^2+y^2,\\ x+y\\ge2\\) \\(2\\lambda-\\tfrac{\\lambda^2}2\\) 2 2 \\(\\min x^2+2y^2,\\ x+y\\ge3\\) \\(3\\lambda-\\tfrac38\\lambda^2\\) 4 6 Bài tập 1: \\(L=x^2+2y^2+\\lambda(3-x-y)\\Rightarrow x=\\tfrac\\lambda2,y=\\tfrac\\lambda4\\Rightarrow q=3\\lambda-\\tfrac38\\lambda^2\\); \\(q^\\prime=0\\Rightarrow\\lambda^*=4\\), \\(q(4)=12-6=6\\)."}, {"id": "d5-slater-vs-dat", "mod": "d5", "term": "Đối ngẫu mạnh, nghiệm đối ngẫu đạt được, Slater", "en": "Slater condition, strong duality, dual attainment, duality gap", "kind": "Mệnh đề", "nomna": "Có hai câu hỏi khác nhau: “hai con số có bằng nhau không?” và “có ai đứng đúng ở con số đó không?”.", "short": "Đối ngẫu mạnh: \\(d^*=p^*\\). Nghiệm đối ngẫu đạt được: \\(\\exists(\\lambda^*,\\nu^*)\\) với \\(q=d^*\\). Slater (bài lồi): có \\(\\bar x\\) với \\(g_i(\\bar x) đủ .", "dn": ["Giá tiệm cận một mức nhưng không chạm mức đó.", "Hai con số bằng nhau chưa chắc có người đứng ở con số đó."], "hay": "Ví dụ Mạnh? Đạt? Yên ngựa? Ví dụ 1 có có (λ=2) có Ví dụ 2 (min x, x²=0) có (0=0) không không Ví dụ 3 (min x, x²=1, x≥0) không (0 — không Ví dụ 2: \\(q(\\nu)=-1/(4\\nu) 0\\) nhưng \\(\\to0\\): sup không đạt."}, {"id": "d5-kkt-yen-ngua", "mod": "d5", "term": "KKT và điểm yên ngựa", "en": "KKT conditions, saddle point, Lagrangian, convex differentiable, global optimality", "kind": "Mệnh đề", "nomna": "KKT là bộ biển báo tại đỉnh tối ưu; điểm yên ngựa là “không ai muốn đổi nước đi”. Với bài lồi hai khái niệm trùng nhau.", "short": "Yên ngựa: \\(L(x^*,\\lambda)\\le L(x^*,\\lambda^*)\\le L(x,\\lambda^*)\\). Nếu nghiệm đạt được: yên ngựa \\(\\iff p^*=d^*\\). Bài lồi khả vi, \\(h\\) affine: KKT \\(\\iff\\) yên ngựa. Không lồi: KKT không đủ.", "dn": ["Hai người chơi cùng đứng yên: không bên nào muốn đổi.", "Biển báo tại đỉnh đồi: dốc bằng 0 và ràng buộc đúng."], "hay": "Bài KKT Tối ưu toàn cục? \\(\\min-x^2,\\ x^2\\le1\\) \\(x=0,\\lambda=0\\) không (cực đại) \\(\\min x^2+y^2,\\ x+y\\ge2\\) \\((1,1;2)\\) có \\(L(x,y,2)=(x-1)^2+(y-1)^2+2\\ge2=L(1,1,\\lambda)\\) mọi \\(\\lambda\\) ⇒ yên ngựa."}, {"id": "d5-dual-ascent", "mod": "d5", "term": "Dual ascent (đi lên trên hàm đối ngẫu)", "en": "dual ascent, supergradient, augmented Lagrangian, ADMM, primal-dual method", "kind": "Thuật toán", "nomna": "Như chỉnh giá: nếu hàng bị bán quá tay (vi phạm ràng buộc) thì tăng giá phạt, nếu dư thì hạ giá.", "short": "\\(x^k\\in\\arg\\min_xL(x,\\lambda^k)\\), \\(\\lambda^{k+1}=[\\lambda^k+\\alpha_kg(x^k)]_+\\). \\(g(x^k)\\) là siêu gradient của \\(q\\) tại \\(\\lambda^k\\).", "dn": ["Chỉnh giá theo mức thiếu/dư hàng.", "Điều chỉnh thuế theo ô nhiễm đo được."], "hay": "k \\(\\lambda^k\\) \\(g(x^k)\\) 0 0 2 1 1 1 2 1.5 0.5 3 1.75 0.25 Ví dụ 1 (\\(\\alpha=0.5\\)): \\(\\lambda^{k+1}-2=0.5(\\lambda^k-2)\\) hội tụ về \\(\\lambda^*=2\\). Với \\(\\alpha=2\\) dao động \\(0,4,0,4\\ldots\\)."}, {"id": "d5-cap-chuan", "mod": "d5", "term": "Cặp LP chuẩn và quy tắc dấu", "en": "standard LP duality, primal dual pair, sign rules, transpose", "kind": "Khái niệm", "nomna": "Bài gốc là xưởng muốn kiếm nhiều nhất; bài đối ngẫu là người thu mua định giá tài nguyên thấp nhất mà xưởng vẫn bán. Dấu của mỗi biến/ràng buộc “lật” theo bảng.", "short": "\\(\\max c^\\top x\\,[Ax\\le b,x\\ge0]\\ \\leftrightarrow\\ \\min b^\\top y\\,[A^\\top y\\ge c,y\\ge0]\\). Hàng ↔ biến \\(y\\); cột ↔ ràng buộc. Gốc max: “≤”→\\(y\\ge0\\), “≥”→\\(y\\le0\\), “=”→tự do; \\(x_j\\ge0\\)→“≥ c_j”, \\(x_j\\le0\\)→“≤ c_j”, tự do→“=”.", "dn": ["Xưởng làm bánh và người định giá bột/đường là hai mặt của một bài.", "Hàng của A là “luật chơi”, cột của A là “giá hợp lý”."], "hay": "Gốc max Đối ngẫu min \\(a_i^\\top x\\le b_i\\) \\(y_i\\ge0\\) \\(a_i^\\top x\\ge b_i\\) \\(y_i\\le0\\) \\(a_i^\\top x=b_i\\) \\(y_i\\) tự do \\(x_j\\ge0\\) \\((A^\\top y)_j\\ge c_j\\) \\(\\max3x_1+2x_2\\), \\(x_1+x_2\\le4\\), \\(2x_1+x_2\\le5\\), \\(x\\ge0\\) ⇒ \\(\\min4y_1+5y_2\\), \\(y_1+2y_2\\ge3\\), \\(y_1+y_2\\ge2\\), \\(y\\ge0\\)."}, {"id": "d5-yeu-bu-lp", "mod": "d5", "term": "Đối ngẫu yếu LP và điều kiện bù trừ", "en": "weak duality LP, complementary slackness, optimality certificate", "kind": "Mệnh đề", "nomna": "Mọi “bảng giá hợp lệ” cho một cận trên của lợi nhuận. Nếu cận trên chạm lợi nhuận đạt được, mọi thứ đều tối ưu và mỗi “giá dương” gắn với một nguồn lực dùng hết.", "short": "\\(c^\\top x\\le y^\\top Ax\\le b^\\top y\\). Bằng nhau ⇔ \\(y_i(b_i-(Ax)_i)=0\\) và \\(x_j((A^\\top y)_j-c_j)=0\\).", "dn": ["Mọi bảng giá hợp lệ cho cận trên; chạm đúng thì đã tối ưu.", "Giá dương chỉ gắn với nguồn lực dùng hết."], "hay": "Kiểm tra Ví dụ (1,3),(1,1) khả thi x \\(4\\le4,\\ 5\\le5\\) khả thi y \\(3\\ge3,\\ 2\\ge2\\) giá trị 9 = 9 bù trừ bốn tích bằng 0 \\(b^\\top y-c^\\top x=\\sum y_i(b_i-(Ax)_i)+\\sum x_j((A^\\top y)_j-c_j)\\), mọi số hạng \\(\\ge0\\)."}, {"id": "d5-lp-lagrange", "mod": "d5", "term": "LP là trường hợp riêng của đối ngẫu Lagrange", "en": "LP as special case of Lagrangian duality, Lagrange dual of LP", "kind": "Mệnh đề", "nomna": "Công thức bảng quy tắc không rơi từ trên trời: nó là kết quả “tính inf của hàm Lagrange tuyến tính”.", "short": "\\(L=-c^\\top x+y^\\top(Ax-b)\\), \\(q(y)=\\inf_{x\\ge0}[(A^\\top y-c)^\\top x-b^\\top y]=-b^\\top y\\) nếu \\(A^\\top y\\ge c\\), \\(-\\infty\\) nếu khác.", "dn": ["Quy tắc dấu là hệ quả của việc tính inf.", "Điều kiện ràng buộc đối ngẫu = điều kiện để cận dưới không bằng −∞."], "hay": "Điều kiện q \\(A^\\top y\\ge c\\) \\(-b^\\top y\\) ngược lại \\(-\\infty\\) Một thành phần \\((A^\\top y-c)_j"}, {"id": "d6-bai-loi", "mod": "d6", "term": "Bài toán tối ưu lồi (dạng hàm)", "en": "convex optimization problem, convex function, affine equality, local equals global minimum", "kind": "Khái niệm", "nomna": "Bài lồi như thung lũng hình bát: chỗ nào thấp nhất cũng là đáy chung, không sợ kẹt ở “hố nhỏ”.", "short": "\\(\\min f(x)\\) s.t. \\(g_i(x)\\le0\\), \\(h_j(x)=0\\) với \\(f,g_i\\) lồi và \\(h_j\\) affine. Cực tiểu địa phương là cực tiểu toàn cục; tập nghiệm là tập lồi.", "dn": ["Thung lũng hình bát: đứng ở đâu thấp nhất cũng là đáy chung.", "Chi phí tuyến tính trên miền đa giác: không có hố nhỏ."], "hay": "Ràng buộc Lồi? \\(x^2\\le4\\) có \\(x^2\\ge4\\) không (g = 4 − x² lõm) \\(x^2=1\\) không (h không affine) \\(x+y\\le2\\) có (affine) \\(f=x^2+y^2\\), \\(x+y\\ge2\\): lồi. \\(\\max x^2+y^2\\) trên đa diện: không lồi."}, {"id": "d6-lop-loi", "mod": "d6", "term": "Các lớp bài toán lồi: LS, LP, QP, QCQP, SOCP, SDP, GP", "en": "LS, LP, QP, QCQP, SOCP, SDP, geometric programming, conic optimization", "kind": "Khái niệm", "nomna": "Mỗi lớp là một “loại xe” có solver riêng; biết lớp là biết dùng công cụ nào.", "short": "LS \\(\\subset\\) QP, LP \\(\\subset\\) QP \\(\\subset\\) QCQP \\(\\subset\\) SOCP \\(\\subset\\) SDP; GP lồi sau đổi biến \\(y=\\ln x\\).", "dn": ["Mỗi loại xe có đường chạy riêng.", "Biết lớp bài toán là biết solver."], "hay": "Lớp Ràng buộc/mục tiêu đặc trưng LP affine QP lồi \\(\\tfrac12x^\\top Px+q^\\top x\\), \\(P\\succeq0\\) SOCP \\(\\lVert Ax+b\\rVert\\le c^\\top x+d\\) SDP \\(\\sum x_iF_i\\succeq G\\) GP posynomial \\(\\min x+y\\), \\(xy\\ge4\\) là GP: \\(x=y=2\\), giá trị 4."}, {"id": "d6-kkt-he", "mod": "d6", "term": "Hệ KKT cho bài có ràng buộc", "en": "KKT system, stationarity, complementary slackness, primal dual feasibility, Lagrange multipliers", "kind": "Khái niệm", "nomna": "Bốn “biển báo” phải đủ tại điểm dừng: không còn hướng giảm, ràng buộc lỏng thì không nhân tử, điểm hợp lệ, nhân tử đúng dấu.", "short": "\\(\\nabla f+\\sum\\lambda_i\\nabla g_i+\\sum\\mu_j\\nabla h_j=0\\); \\(\\lambda_ig_i=0\\); \\(g\\le0,h=0\\); \\(\\lambda\\ge0\\), \\(\\mu\\in\\mathbb R\\).", "dn": ["Bốn biển báo phải đủ.", "Ràng buộc lỏng thì không đẩy."], "hay": "Điều kiện Tên \\(\\nabla_xL=0\\) dừng \\(\\lambda_ig_i=0\\) bù trừ \\(g\\le0,h=0\\) khả thi \\(\\lambda\\ge0\\) dấu Ví dụ 4: \\(x^*=(1,1)\\), \\(\\lambda=(2,0,0)\\)."}, {"id": "d6-can-chinh-quy", "mod": "d6", "term": "Điều kiện cần cần chính quy; Fritz John", "en": "constraint qualification, LICQ, MFCQ, Fritz John conditions, necessary optimality", "kind": "Mệnh đề", "nomna": "KKT chỉ “bắt buộc” khi miền đủ đẹp tại nghiệm; nếu không, nghiệm tối ưu có thể không có nhân tử.", "short": "Tối ưu địa phương + chính quy (LICQ, MFCQ; Slater cho bài lồi) ⇒ tồn tại \\((\\lambda,\\mu)\\), \\(\\lambda\\ge0\\), thoả KKT. Không chính quy: chỉ có dạng Fritz John (nhân tử của \\(f\\) cho phép 0). Cụm “không đồng thời bằng 0” ở slide thuộc dạng này.", "dn": ["Khe dày bằng 0 không truyền được lực.", "Nghiệm tối ưu mà không có nhân tử."], "hay": "Bài Nghiệm Nhân tử KKT? \\(\\min x,\\ x^2\\le0\\) 0 không có \\(\\min x^2,\\ x\\le1\\) 0 có, \\(\\lambda=0\\) \\(\\min x\\), \\(x^2\\le0\\): \\(1+\\lambda\\cdot2\\cdot0\\ne0\\) ∀λ."}, {"id": "d6-slater-ket-qua", "mod": "d6", "term": "Slater và hệ quả", "en": "Slater constraint qualification, strong duality, KKT necessary and sufficient, convex", "kind": "Mệnh đề", "nomna": "Slater nói miền khả thi có “chỗ rộng” bên trong; nhờ vậy đối ngẫu không bị hỏng.", "short": "Bài lồi, \\(p^*\\) hữu hạn và \\(\\exists z\\in\\Omega\\) với mọi \\(g_i(z) chỉ đủ .", "dn": ["Có chỗ rộng bên trong miền.", "Điều kiện đủ, không cần."], "hay": "Bài Slater Đối ngẫu mạnh \\(\\min x,\\ x^2\\le0\\) không có (không đạt) tr.57 (hai tia) không có (đã kiểm) \\(\\min x,\\ x^2=1,x\\ge0\\) không không tr.57: \\(\\lambda=(1,1),\\mu=0\\) cho \\(q=0=p^*\\)."}, {"id": "d6-diem-kkt-phi-loi", "mod": "d6", "term": "Điểm KKT của bài không lồi", "en": "KKT point nonconvex, saddle point, stationary point, local maximum", "kind": "Khái niệm", "nomna": "Biển báo dừng có thể ở đáy, đỉnh hoặc yên ngựa.", "short": "Bài không lồi: điểm KKT chỉ là điểm dừng. Cần thêm điều kiện cấp hai hoặc so giá trị để phân loại.", "dn": ["Đèo núi là điểm dừng.", "Biển báo dừng ở đỉnh hay đáy đều như nhau."], "hay": "Bài Điểm KKT Loại \\(\\min xy,\\ x^2+y^2\\le2\\) \\((0,0)\\) yên ngựa \\(\\min xy\\) \\((\\pm1,\\mp1)\\) cực tiểu toàn cục Ví dụ 3: ba điểm KKT; \\((1,1)\\) cực đại bị loại vì \\(\\lambda"}, {"id": "d6-tap-nghiem", "mod": "d6", "term": "Tập nghiệm và số nghiệm của bài lồi", "en": "solution set convex problem, unique minimizer, strictly convex, number of solutions", "kind": "Mệnh đề", "nomna": "Đã có hai nghiệm thì có cả đoạn nối; nên không có chuyện “đúng hai nghiệm”.", "short": "Tập nghiệm \\(S=\\{x\\in C:f(x)\\le p^*\\}\\) lồi. Số nghiệm: 0, 1 hoặc vô số. Nghiệm duy nhất nếu \\(f\\) lồi chặt.", "dn": ["Hai phương án tối ưu thì mọi phương án trộn cũng tối ưu.", "Không có chuyện đúng hai."], "hay": "Tình huống Số nghiệm \\(f\\) lồi chặt ≤ 1 \\(\\min0\\) trên \\([0,1]\\) vô số LP có tối ưu duy nhất 1 (đỉnh) \\(x_t=(1-t)x_1+tx_2\\) tối ưu ∀\\(t\\in[0,1]\\)."}, {"id": "d6-nhan-tu-duy-nhat", "mod": "d6", "term": "Nhân tử có duy nhất không?", "en": "uniqueness of Lagrange multipliers, LICQ, set of multipliers, degenerate constraints", "kind": "Mệnh đề", "nomna": "Nếu hai ràng buộc “chồng” lên nhau thì lực có thể chia đôi nhiều cách.", "short": "Nhân tử không nhất thiết duy nhất. Duy nhất khi các gradient ràng buộc chặt độc lập tuyến tính (LICQ). Nói chung tập nhân tử là đa diện lồi.", "dn": ["Hai dây cáp chia tải nhiều cách.", "Ràng buộc trùng nhau."], "hay": "Bài Nhân tử \\(\\min x,\\ -x\\le0\\) lặp hai lần \\(\\lambda_1+\\lambda_2=1\\), vô số Ví dụ 4 \\(\\lambda=(2,0,0)\\) duy nhất Ràng buộc trùng: \\(1-\\lambda_1-\\lambda_2=0\\)."}];
